export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const palette = [
    { name: 'Sky Blue', hex: 0x22aaff, css: '#22aaff' },
    { name: 'Ruby Red', hex: 0xff3355, css: '#ff3355' },
    { name: 'Tangerine Orange', hex: 0xff8c1a, css: '#ff8c1a' },
    { name: 'Sun Yellow', hex: 0xffd21f, css: '#ffd21f' },
    { name: 'Lime Green', hex: 0x3ee05a, css: '#3ee05a' },
    { name: 'Teal', hex: 0x00e5c0, css: '#00e5c0' },
    { name: 'Violet Purple', hex: 0xa259ff, css: '#a259ff' },
    { name: 'Hot Pink', hex: 0xff4fd8, css: '#ff4fd8' },
  ];

  let currentIndex = 0;
  let pressCount = 0;
  let pressAnim = 0;
  let rippleT = 1;

  const targetColor = new THREE.Color(palette[0].hex);

  // Desk glow halo
  const haloMat = new THREE.MeshBasicMaterial({
    color: palette[0].hex,
    transparent: true,
    opacity: 0.32,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const halo = new THREE.Mesh(new THREE.RingGeometry(0.11, 0.17, 48), haloMat);
  halo.rotation.x = -Math.PI / 2;
  halo.position.set(0, 0.003, 0.08);
  root.add(halo);

  // Expanding ripple shown on each press
  const rippleMat = new THREE.MeshBasicMaterial({
    color: palette[0].hex,
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const ripple = new THREE.Mesh(new THREE.RingGeometry(0.09, 0.105, 48), rippleMat);
  ripple.rotation.x = -Math.PI / 2;
  ripple.position.set(0, 0.004, 0.08);
  root.add(ripple);

  // Pedestal
  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(0.09, 0.105, 0.02, 48),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.45, metalness: 0.55 })
  );
  base.name = 'ButtonBase';
  base.position.set(0, 0.01, 0.08);
  root.add(base);

  // Metal socket ring around the button
  const socket = new THREE.Mesh(
    new THREE.TorusGeometry(0.06, 0.007, 12, 48),
    new THREE.MeshStandardMaterial({ color: 0xd0d6e0, roughness: 0.25, metalness: 0.85 })
  );
  socket.rotation.x = Math.PI / 2;
  socket.position.set(0, 0.022, 0.08);
  root.add(socket);

  // The glowing pressable button - a single large dome so it is easy to press
  const buttonMat = new THREE.MeshStandardMaterial({
    color: palette[0].hex,
    emissive: palette[0].hex,
    emissiveIntensity: 2.0,
    roughness: 0.25,
    metalness: 0.05,
  });
  const button = new THREE.Mesh(new THREE.SphereGeometry(0.065, 32, 16), buttonMat);
  button.name = 'GlowButton';
  button.position.set(0, 0.042, 0.08);
  button.scale.set(1, 0.5, 1);
  root.add(button);

  // Floating glow particles that follow the button color
  const particleMat = new THREE.MeshBasicMaterial({
    color: palette[0].hex,
    transparent: true,
    opacity: 0.9,
  });
  const particleCount = 12;
  const particles = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.006, 8, 6),
    particleMat,
    particleCount
  );
  particles.name = 'GlowParticles';
  particles.position.set(0, 0.1, 0.08);
  root.add(particles);

  const particleRadii = [0.11, 0.13, 0.15, 0.12, 0.16, 0.14, 0.11, 0.17, 0.13, 0.15, 0.12, 0.16];
  const particleSpeeds = [0.45, 0.35, 0.5, 0.4, 0.3, 0.42, 0.48, 0.34, 0.44, 0.38, 0.5, 0.36];
  const particleOffsets = [0, 0.5, 1.0, 1.5, 2.0, 2.6, 3.1, 3.7, 4.2, 4.8, 5.3, 5.8];
  const particleHeights = [0.02, -0.02, 0.04, 0.0, -0.03, 0.03, -0.01, 0.05, 0.01, -0.02, 0.03, 0.0];

  const glowMaterials = [buttonMat, haloMat, rippleMat, particleMat];

  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .row { flex-direction: row; gap: 8px; align-items: center; }
      .label { color: #d7dbe2; font-size: 23px; }
      .colorName { color: #ffffff; font-size: 25px; font-weight: 700; }
      .swatch { width: 150px; height: 18px; border-radius: 9px; background-color: #22aaff; }
      .btn { padding-top: 11px; padding-bottom: 11px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 23px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Glowing Color Button</span>
      <span class="body">Press the glowing dome in front of you. Every press changes it to a new color.</span>
      <div class="row"><span class="label">Current color:</span><span id="colorName" class="colorName">Sky Blue</span></div>
      <div id="swatch" class="swatch"></div>
      <span id="pressCount" class="body">Presses: 0</span>
      <button id="change" class="btn"><span class="btn-text">Change color</span></button>
    </div>`, { width: 0.34, position: [0, 0.32, -0.1], rotationY: 0 });
  root.add(info.object3D);

  function changeColor() {
    currentIndex = (currentIndex + 1) % palette.length;
    pressCount += 1;
    pressAnim = 1;
    rippleT = 0;
    const entry = palette[currentIndex];
    targetColor.setHex(entry.hex);
    info.set('colorName', { text: entry.name });
    info.set('swatch', { backgroundColor: entry.css });
    info.set('pressCount', { text: 'Presses: ' + pressCount });
  }

  traits(button, { onPress: changeColor });
  info.on('change', 'click', changeColor);

  const dummy = new THREE.Object3D();

  return {
    root,
    update(time, delta) {
      const dt = delta || 0.016;

      // Smoothly blend all glow materials toward the target color
      const k = 1 - Math.exp(-12 * dt);
      for (let i = 0; i < glowMaterials.length; i++) {
        const mat = glowMaterials[i];
        mat.color.lerp(targetColor, k);
        if (mat.emissive) mat.emissive.lerp(targetColor, k);
      }

      // Idle glow pulse plus a bright flash right after a press
      pressAnim = Math.max(0, pressAnim - dt * 2.8);
      buttonMat.emissiveIntensity = 1.9 + Math.sin(time * 2.5) * 0.35 + pressAnim * 1.4;

      // Squash and bulge the button like a real press
      button.scale.set(1 + 0.1 * pressAnim, 0.5 * (1 - 0.38 * pressAnim), 1 + 0.1 * pressAnim);

      haloMat.opacity = 0.3 + Math.sin(time * 2.5) * 0.08 + pressAnim * 0.15;

      // Expanding ripple ring
      if (rippleT < 1) {
        rippleT = Math.min(1, rippleT + dt * 1.4);
        ripple.scale.setScalar(1 + rippleT * 1.7);
        rippleMat.opacity = 0.65 * (1 - rippleT);
      } else {
        rippleMat.opacity = 0;
      }

      // Slowly orbiting glow particles around the button
      for (let i = 0; i < particleCount; i++) {
        const angle = time * particleSpeeds[i] + particleOffsets[i];
        dummy.position.set(
          Math.cos(angle) * particleRadii[i],
          particleHeights[i] + Math.sin(time * 1.2 + particleOffsets[i]) * 0.015,
          Math.sin(angle) * particleRadii[i]
        );
        dummy.updateMatrix();
        particles.setMatrixAt(i, dummy.matrix);
      }
      particles.instanceMatrix.needsUpdate = true;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const BP_COUNT = 14;
  const HELIX_HEIGHT = 0.30;
  const RADIUS = 0.042;
  const TWIST_PER_BP = (Math.PI * 2) / 10.5;

  const helix = new THREE.Group();
  helix.name = 'DNA double helix';
  helix.position.set(-0.15, 0.21, 0);
  helix.rotation.y = 0.4;
  root.add(helix);

  const backboneMaterial = new THREE.MeshStandardMaterial({ color: 0xf0e6cf, roughness: 0.35, metalness: 0.05 });
  const phosphateMaterial = new THREE.MeshStandardMaterial({ color: 0xc2cad4, roughness: 0.4, metalness: 0.1 });
  const baseMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.35, metalness: 0.0 });

  const pointsA = [];
  const pointsB = [];
  for (let i = 0; i < BP_COUNT; i++) {
    const y = -HELIX_HEIGHT / 2 + (HELIX_HEIGHT / (BP_COUNT - 1)) * i;
    const a = i * TWIST_PER_BP;
    pointsA.push(new THREE.Vector3(Math.cos(a) * RADIUS, y, Math.sin(a) * RADIUS));
    pointsB.push(new THREE.Vector3(Math.cos(a + Math.PI) * RADIUS, y, Math.sin(a + Math.PI) * RADIUS));
  }

  const curveA = new THREE.CatmullRomCurve3(pointsA);
  const curveB = new THREE.CatmullRomCurve3(pointsB);

  const strandA = new THREE.Mesh(new THREE.TubeGeometry(curveA, 160, 0.0068, 10, false), backboneMaterial);
  strandA.name = 'Backbone strand 1';
  helix.add(strandA);

  const strandB = new THREE.Mesh(new THREE.TubeGeometry(curveB, 160, 0.0068, 10, false), backboneMaterial);
  strandB.name = 'Backbone strand 2';
  helix.add(strandB);

  const dummy = new THREE.Object3D();

  const phosphates = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.0098, 18, 12),
    phosphateMaterial,
    BP_COUNT * 2
  );
  phosphates.name = 'Phosphate backbone';
  for (let i = 0; i < BP_COUNT; i++) {
    dummy.position.copy(pointsA[i]);
    dummy.rotation.set(0, 0, 0);
    dummy.updateMatrix();
    phosphates.setMatrixAt(i * 2, dummy.matrix);
    dummy.position.copy(pointsB[i]);
    dummy.updateMatrix();
    phosphates.setMatrixAt(i * 2 + 1, dummy.matrix);
  }
  helix.add(phosphates);

  const bases = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.0165, 20, 14),
    baseMaterial,
    BP_COUNT * 2
  );
  bases.name = 'Base pairs';
  for (let i = 0; i < BP_COUNT; i++) {
    const y = -HELIX_HEIGHT / 2 + (HELIX_HEIGHT / (BP_COUNT - 1)) * i;
    const a = i * TWIST_PER_BP;
    dummy.position.set(Math.cos(a) * 0.022, y, Math.sin(a) * 0.022);
    dummy.updateMatrix();
    bases.setMatrixAt(i * 2, dummy.matrix);
    dummy.position.set(Math.cos(a + Math.PI) * 0.022, y, Math.sin(a + Math.PI) * 0.022);
    dummy.updateMatrix();
    bases.setMatrixAt(i * 2 + 1, dummy.matrix);
  }
  helix.add(bases);

  const standMaterial = new THREE.MeshStandardMaterial({ color: 0x39404d, roughness: 0.6, metalness: 0.2 });
  const pedestal = new THREE.Mesh(new THREE.CylinderGeometry(0.066, 0.072, 0.014, 32), standMaterial);
  pedestal.name = 'Stand';
  pedestal.position.set(-0.15, 0.007, 0);
  root.add(pedestal);

  const rod = new THREE.Mesh(
    new THREE.CylinderGeometry(0.004, 0.004, 0.055, 12),
    new THREE.MeshStandardMaterial({ color: 0x8a939e, roughness: 0.35, metalness: 0.6 })
  );
  rod.name = 'Support rod';
  rod.position.set(-0.15, 0.041, 0);
  root.add(rod);

  const sequences = [
    'ATGCGTACGTTGCA',
    'GCATTAACGGCATG',
    'TTGACCGATTACGA',
    'CAGATCTTGAGTAC'
  ];
  const complement = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const baseColors = {
    A: new THREE.Color(0x2fd06b),
    T: new THREE.Color(0xef4b4b),
    G: new THREE.Color(0xffb020),
    C: new THREE.Color(0x3f8cff)
  };

  let seqIndex = 0;
  let spinning = true;
  let panel = null;

  function applySequence() {
    const seq = sequences[seqIndex];
    let comp = '';
    for (let i = 0; i < BP_COUNT; i++) {
      const a = seq[i];
      const b = complement[a];
      comp += b;
      bases.setColorAt(i * 2, baseColors[a]);
      bases.setColorAt(i * 2 + 1, baseColors[b]);
    }
    if (bases.instanceColor) bases.instanceColor.needsUpdate = true;
    panel.set('seq1', { text: "5' " + seq + " 3'" });
    panel.set('seq2', { text: "3' " + comp + " 5'" });
  }

  panel = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; border-width: 2px; border-color: #3a3f48; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .fact { color: #aeb6c2; font-size: 20px; }
      .legend { display: flex; flex-direction: row; gap: 14px; align-items: center; }
      .legend-item { display: flex; flex-direction: row; gap: 6px; align-items: center; }
      .dot { width: 16px; height: 16px; border-radius: 8px; }
      .dot-a { background-color: #2fd06b; }
      .dot-t { background-color: #ef4b4b; }
      .dot-g { background-color: #ffb020; }
      .dot-c { background-color: #3f8cff; }
      .legend-text { color: #ffffff; font-size: 20px; font-weight: 700; }
      .seq { color: #ffd76d; font-size: 20px; font-weight: 700; }
      .row { display: flex; flex-direction: row; gap: 12px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f6fdb; border-width: 0px; border-color: #2f6fdb; }
      .btn-secondary { background-color: #39404d; border-color: #39404d; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="body" id="info">Pinch the helix and turn it around in your hands. The two strands twist around each other and run in opposite directions.</span>
      <span class="fact">B-DNA is about 2 nm wide, with 10.5 base pairs per full turn. A pairs with T, and G pairs with C.</span>
      <div class="legend">
        <div class="legend-item"><div class="dot dot-a"></div><span class="legend-text">A</span></div>
        <div class="legend-item"><div class="dot dot-t"></div><span class="legend-text">T</span></div>
        <div class="legend-item"><div class="dot dot-g"></div><span class="legend-text">G</span></div>
        <div class="legend-item"><div class="dot dot-c"></div><span class="legend-text">C</span></div>
      </div>
      <span class="seq" id="seq1">5' ATGCGTACGTTGCA 3'</span>
      <span class="seq" id="seq2">3' TACGCATGCAACGT 5'</span>
      <div class="row">
        <button class="btn" id="spinBtn"><span class="btn-text" id="spinLabel">Pause spin</span></button>
        <button class="btn btn-secondary" id="newBtn"><span class="btn-text">New sequence</span></button>
      </div>
    </div>`, { width: 0.32, position: [0.23, 0.24, 0.02], rotationY: -0.28 });
  root.add(panel.object3D);

  panel.on('spinBtn', 'click', () => {
    spinning = !spinning;
    panel.set('spinLabel', { text: spinning ? 'Pause spin' : 'Start spin' });
    panel.set('info', {
      text: spinning
        ? 'Spinning slowly. Pinch the helix and turn it around yourself.'
        : 'Spin paused. Pinch the helix and turn it around yourself.'
    });
  });

  panel.on('newBtn', 'click', () => {
    seqIndex = (seqIndex + 1) % sequences.length;
    applySequence();
    panel.set('info', { text: 'New sequence loaded. A pairs with T, and G pairs with C. Pinch the helix to inspect it.' });
  });

  traits(helix, { grab: true });
  applySequence();

  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) return;
      if (spinning) helix.rotation.y += delta * 0.45;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  let hue = 0.58;
  let pressCount = 0;
  let pressStart = -10;
  let now = 0;

  const tmpColor = new THREE.Color();
  tmpColor.setHSL(hue, 1, 0.58);

  function colorNameFor(h) {
    if (h < 0.04 || h >= 0.95) return 'Ruby Red';
    if (h < 0.09) return 'Tangerine Orange';
    if (h < 0.17) return 'Sunshine Yellow';
    if (h < 0.28) return 'Lime Green';
    if (h < 0.40) return 'Emerald Green';
    if (h < 0.52) return 'Teal Cyan';
    if (h < 0.68) return 'Electric Blue';
    if (h < 0.83) return 'Violet Purple';
    return 'Hot Pink';
  }

  const buttonMat = new THREE.MeshStandardMaterial({
    color: tmpColor.clone(),
    emissive: tmpColor.clone(),
    emissiveIntensity: 1.3,
    roughness: 0.32,
    metalness: 0.05
  });

  const haloMat = new THREE.MeshBasicMaterial({
    color: tmpColor.clone(),
    transparent: true,
    opacity: 0.32,
    side: THREE.DoubleSide,
    depthWrite: false
  });

  const haloMat2 = new THREE.MeshBasicMaterial({
    color: tmpColor.clone(),
    transparent: true,
    opacity: 0.16,
    side: THREE.DoubleSide,
    depthWrite: false
  });

  const pedestal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.09, 0.1, 0.024, 32),
    new THREE.MeshStandardMaterial({ color: 0x23262c, roughness: 0.8, metalness: 0.1 })
  );
  pedestal.name = 'Pedestal';
  pedestal.position.set(0, 0.012, 0.06);
  root.add(pedestal);

  const glowDisc = new THREE.Mesh(new THREE.CircleGeometry(0.07, 32), buttonMat);
  glowDisc.name = 'PedestalGlow';
  glowDisc.position.set(0, 0.025, 0.06);
  glowDisc.rotation.x = -Math.PI / 2;
  root.add(glowDisc);

  const button = new THREE.Mesh(
    new THREE.CylinderGeometry(0.05, 0.056, 0.032, 48),
    buttonMat
  );
  button.name = 'GlowButton';
  button.position.set(0, 0.13, 0.06);
  button.rotation.x = Math.PI / 2;
  root.add(button);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.07, 0.006, 12, 48), buttonMat);
  rim.name = 'GlowRim';
  rim.position.set(0, 0.13, 0.04);
  root.add(rim);

  const halo = new THREE.Mesh(new THREE.RingGeometry(0.082, 0.118, 48), haloMat);
  halo.name = 'GlowHalo';
  halo.position.set(0, 0.13, 0.035);
  root.add(halo);

  const halo2 = new THREE.Mesh(new THREE.RingGeometry(0.124, 0.17, 48), haloMat2);
  halo2.name = 'GlowHaloOuter';
  halo2.position.set(0, 0.13, 0.03);
  root.add(halo2);

  const orbs = [];
  const orbGeometry = new THREE.SphereGeometry(0.009, 16, 12);
  for (let i = 0; i < 5; i++) {
    const orb = new THREE.Mesh(orbGeometry, buttonMat);
    orb.name = 'GlowOrb';
    orb.position.set(0.1, 0.13, 0.06);
    root.add(orb);
    orbs.push(orb);
  }

  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 20px; background-color: #1a1d22;
              border-color: #3a3f47; border-width: 2px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; text-align: center; }
      .row { display: flex; flex-direction: row; align-items: center; justify-content: center; gap: 16px; }
      .swatch { width: 48px; height: 48px; border-radius: 24px; background-color: #2f9bff;
                border-width: 2px; border-color: #ffffff; }
      .col { display: flex; flex-direction: column; gap: 2px; }
      .name { color: #ffffff; font-size: 26px; font-weight: 700; }
      .hex { color: #aab0ba; font-size: 20px; }
      .count { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Glow Button</span>
      <span class="body">Pinch or poke the big glowing button. Every press gives it a brand new color.</span>
      <div class="row">
        <div class="swatch" id="swatch"></div>
        <div class="col">
          <span class="name" id="colorName">Electric Blue</span>
          <span class="hex" id="hex">#000000</span>
        </div>
      </div>
      <span class="count" id="count">Presses: 0</span>
    </div>`, { width: 0.34, position: [0, 0.36, 0], rotationY: 0 });
  root.add(info.object3D);

  function syncPanel() {
    const css = '#' + tmpColor.getHexString();
    info.set('colorName', { text: colorNameFor(hue) });
    info.set('hex', { text: css.toUpperCase() });
    info.set('count', { text: 'Presses: ' + pressCount });
    info.set('swatch', { backgroundColor: css });
  }
  syncPanel();

  traits(button, {
    onPress: () => {
      pressCount += 1;
      hue = (hue + 0.17) % 1;
      tmpColor.setHSL(hue, 1, 0.58);
      buttonMat.color.copy(tmpColor);
      buttonMat.emissive.copy(tmpColor);
      haloMat.color.copy(tmpColor);
      haloMat2.color.copy(tmpColor);
      pressStart = now;
      syncPanel();
    }
  });

  return {
    root,
    update(time) {
      now = time;

      const pulse = 0.5 + 0.5 * Math.sin(time * 3);
      buttonMat.emissiveIntensity = 1.15 + 0.45 * pulse;
      haloMat.opacity = 0.24 + 0.14 * pulse;
      haloMat2.opacity = 0.1 + 0.08 * pulse;

      const haloScale = 1 + 0.04 * pulse;
      halo.scale.set(haloScale, haloScale, 1);
      halo2.scale.set(haloScale, haloScale, 1);

      let press = 0;
      const since = time - pressStart;
      if (since >= 0 && since < 0.28) {
        press = Math.sin((since / 0.28) * Math.PI);
      }
      button.scale.set(1 + 0.07 * press, 1 - 0.35 * press, 1 + 0.07 * press);
      button.position.z = 0.06 - 0.012 * press;

      for (let i = 0; i < orbs.length; i++) {
        const orb = orbs[i];
        const angle = time * 0.55 + i * 1.2566;
        orb.position.set(
          Math.cos(angle) * 0.1,
          0.13 + Math.sin(angle) * 0.1,
          0.06 + Math.sin(time * 0.9 + i * 1.7) * 0.012
        );
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const bases = ['A', 'T', 'C', 'G', 'A', 'A', 'T', 'C', 'G', 'T', 'A', 'C', 'G', 'T', 'A', 'C'];
  const complement = { A: 'T', T: 'A', C: 'G', G: 'C' };
  const baseInfo = {
    A: { name: 'Adenine', color: 0x2ecc71 },
    T: { name: 'Thymine', color: 0xe74c3c },
    C: { name: 'Cytosine', color: 0x3498db },
    G: { name: 'Guanine', color: 0xf5b041 },
  };
  const baseMats = {};
  for (const b of ['A', 'T', 'C', 'G']) {
    baseMats[b] = new THREE.MeshStandardMaterial({ color: baseInfo[b].color, roughness: 0.35, metalness: 0.05 });
  }

  const N = 16;
  const R = 0.056;
  const HEIGHT = 0.28;
  const step = (Math.PI * 2) / 10;

  const points1 = [];
  const points2 = [];
  for (let i = 0; i < N; i++) {
    const y = -HEIGHT / 2 + i * (HEIGHT / (N - 1));
    const theta = i * step;
    const x = Math.cos(theta) * R;
    const z = Math.sin(theta) * R;
    points1.push(new THREE.Vector3(x, y, z));
    points2.push(new THREE.Vector3(-x, y, -z));
  }

  // Display tray under the DNA
  const tray = new THREE.Mesh(
    new THREE.CylinderGeometry(0.115, 0.12, 0.012, 36),
    new THREE.MeshStandardMaterial({ color: 0x1f3a46, roughness: 0.85 })
  );
  tray.name = 'Display Tray';
  tray.position.set(-0.17, 0.006, 0);
  root.add(tray);

  const trayRing = new THREE.Mesh(
    new THREE.TorusGeometry(0.095, 0.003, 8, 48),
    new THREE.MeshStandardMaterial({ color: 0x4fb3c9, emissive: 0x1b5a6a, emissiveIntensity: 0.6, roughness: 0.4 })
  );
  trayRing.name = 'Tray Ring';
  trayRing.rotation.x = Math.PI / 2;
  trayRing.position.set(-0.17, 0.013, 0);
  root.add(trayRing);

  // The grabbable DNA helix
  const dna = new THREE.Group();
  dna.name = 'DNA Double Helix';
  const initialPos = new THREE.Vector3(-0.17, 0.235, 0);
  dna.position.copy(initialPos);
  dna.rotation.y = 0.4;
  root.add(dna);

  const backboneMat = new THREE.MeshStandardMaterial({ color: 0xf0f4f8, roughness: 0.3, metalness: 0.05 });

  const curve1 = new THREE.CatmullRomCurve3(points1);
  const curve2 = new THREE.CatmullRomCurve3(points2);
  const strand1 = new THREE.Mesh(new THREE.TubeGeometry(curve1, 80, 0.008, 10, false), backboneMat);
  strand1.name = 'Backbone Strand 1';
  dna.add(strand1);
  const strand2 = new THREE.Mesh(new THREE.TubeGeometry(curve2, 80, 0.008, 10, false), backboneMat);
  strand2.name = 'Backbone Strand 2';
  dna.add(strand2);

  // Backbone beads
  const beadGeo = new THREE.SphereGeometry(0.013, 20, 14);
  const beads = new THREE.InstancedMesh(beadGeo, backboneMat, N * 2);
  beads.name = 'Backbone Beads';
  const dummy = new THREE.Object3D();
  let beadIndex = 0;
  for (let i = 0; i < N; i++) {
    dummy.position.copy(points1[i]);
    dummy.updateMatrix();
    beads.setMatrixAt(beadIndex++, dummy.matrix);
    dummy.position.copy(points2[i]);
    dummy.updateMatrix();
    beads.setMatrixAt(beadIndex++, dummy.matrix);
  }
  beads.instanceMatrix.needsUpdate = true;
  dna.add(beads);

  // Base pair rungs, split into two colored halves
  const rungGeo = new THREE.CylinderGeometry(0.0062, 0.0062, 1, 10);
  const up = new THREE.Vector3(0, 1, 0);
  const rungHalves = [];
  for (let i = 0; i < N; i++) {
    const y = points1[i].y;
    const theta = i * step;
    const radial = new THREE.Vector3(Math.cos(theta), 0, Math.sin(theta));
    const b1 = bases[i];
    const b2 = complement[b1];

    const mid1 = new THREE.Vector3(radial.x * R * 0.5, y, radial.z * R * 0.5);
    const mesh1 = new THREE.Mesh(rungGeo, baseMats[b1]);
    mesh1.name = 'Base ' + b1;
    mesh1.position.copy(mid1);
    mesh1.scale.set(1, R, 1);
    mesh1.quaternion.setFromUnitVectors(up, radial);
    dna.add(mesh1);
    rungHalves.push({ mesh: mesh1, orig: mid1.clone(), radial: radial.clone() });

    const mid2 = new THREE.Vector3(-mid1.x, y, -mid1.z);
    const radial2 = new THREE.Vector3(-radial.x, 0, -radial.z);
    const mesh2 = new THREE.Mesh(rungGeo, baseMats[b2]);
    mesh2.name = 'Base ' + b2;
    mesh2.position.copy(mid2);
    mesh2.scale.set(1, R, 1);
    mesh2.quaternion.setFromUnitVectors(up, radial2);
    dna.add(mesh2);
    rungHalves.push({ mesh: mesh2, orig: mid2.clone(), radial: radial2.clone() });
  }

  // Gold marker at the top so orientation is clear when turning it
  const marker = new THREE.Mesh(
    new THREE.ConeGeometry(0.013, 0.028, 16),
    new THREE.MeshStandardMaterial({ color: 0xffd93d, emissive: 0xcc9900, emissiveIntensity: 0.5, roughness: 0.35 })
  );
  marker.name = 'Top Marker';
  marker.position.copy(points1[N - 1]);
  marker.position.y += 0.022;
  dna.add(marker);

  // Highlight ring for the selected base pair
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(0.073, 0.0045, 8, 40),
    new THREE.MeshBasicMaterial({ color: 0xffe066 })
  );
  ring.name = 'Selected Pair Highlight';
  ring.rotation.x = Math.PI / 2;
  ring.position.y = points1[0].y;
  dna.add(ring);

  // Info panel
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1a1d22; border-color: #333a44; border-width: 1px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; text-align: center; }
      .small { color: #aeb6c2; font-size: 22px; text-align: center; }
      .legend { flex-direction: column; gap: 5px; align-items: center; }
      .legendRow { flex-direction: row; gap: 10px; align-items: center; justify-content: center; }
      .dot { width: 16px; height: 16px; border-radius: 8px; }
      .dotA { background-color: #2ecc71; }
      .dotT { background-color: #e74c3c; }
      .dotC { background-color: #3498db; }
      .dotG { background-color: #f5b041; }
      .legendText { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; gap: 8px; align-items: center; justify-content: center; }
      .btn { padding-top: 9px; padding-bottom: 9px; padding-left: 12px; padding-right: 12px; border-radius: 10px; background-color: #2f6fdb; border-color: #2f6fdb; border-width: 1px; }
      .btnText { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="body">Pinch the DNA to pick it up and turn it around to see all sides.</span>
      <div class="legend">
        <div class="legendRow"><span class="dot dotA"></span><span class="legendText">A - Adenine</span></div>
        <div class="legendRow"><span class="dot dotT"></span><span class="legendText">T - Thymine</span></div>
        <div class="legendRow"><span class="dot dotC"></span><span class="legendText">C - Cytosine</span></div>
        <div class="legendRow"><span class="dot dotG"></span><span class="legendText">G - Guanine</span></div>
      </div>
      <span class="body" id="pairInfo">Pair 1 of 16: A - T (Adenine - Thymine) - 2 hydrogen bonds.</span>
      <span class="small">White tubes and beads form the backbone. Colored rungs are the base pairs.</span>
      <span class="small">A pairs with T with 2 hydrogen bonds. C pairs with G with 3 hydrogen bonds.</span>
      <span class="small">The two strands run in opposite directions.</span>
      <div class="row">
        <button class="btn" id="prevPair"><span class="btnText">Prev pair</span></button>
        <button class="btn" id="nextPair"><span class="btnText">Next pair</span></button>
      </div>
      <div class="row">
        <button class="btn" id="spinBtn"><span class="btnText" id="spinLabel">Spin: On</span></button>
        <button class="btn" id="explodeBtn"><span class="btnText" id="explodeLabel">Explode: Off</span></button>
        <button class="btn" id="resetBtn"><span class="btnText">Reset view</span></button>
      </div>
    </div>`, { width: 0.28, position: [0.24, 0.26, 0.04], rotationY: -0.25 });
  root.add(info.object3D);

  let selected = 0;
  let spinning = true;
  let exploding = false;
  let explodeAmount = 0;

  function pairText() {
    const b1 = bases[selected];
    const b2 = complement[b1];
    const bonds = (b1 === 'A' || b1 === 'T') ? 2 : 3;
    return 'Pair ' + (selected + 1) + ' of 16: ' + b1 + ' - ' + b2 + ' (' + baseInfo[b1].name + ' - ' + baseInfo[b2].name + ') - ' + bonds + ' hydrogen bonds.';
  }
  function refreshPair() {
    info.set('pairInfo', { text: pairText() });
    ring.position.y = points1[selected].y;
  }
  refreshPair();

  info.on('prevPair', 'click', () => { selected = (selected - 1 + N) % N; refreshPair(); });
  info.on('nextPair', 'click', () => { selected = (selected + 1) % N; refreshPair(); });
  info.on('spinBtn', 'click', () => { spinning = !spinning; info.set('spinLabel', { text: spinning ? 'Spin: On' : 'Spin: Off' }); });
  info.on('explodeBtn', 'click', () => { exploding = !exploding; info.set('explodeLabel', { text: exploding ? 'Explode: On' : 'Explode: Off' }); });
  info.on('resetBtn', 'click', () => { dna.position.copy(initialPos); dna.rotation.set(0, 0.4, 0); });

  traits(dna, { grab: true });

  return {
    root,
    update(time, delta) {
      if (!isGrabbed(dna) && spinning) {
        dna.rotation.y += delta * 0.35;
      }
      const target = exploding ? 1 : 0;
      if (explodeAmount < target) explodeAmount = Math.min(target, explodeAmount + delta * 1.2);
      else if (explodeAmount > target) explodeAmount = Math.max(target, explodeAmount - delta * 1.2);
      const offset = explodeAmount * 0.032;
      for (let i = 0; i < rungHalves.length; i++) {
        const h = rungHalves[i];
        h.mesh.position.copy(h.orig).addScaledVector(h.radial, offset);
      }
      const s = 1 + Math.sin(time * 3) * 0.05;
      ring.scale.set(s, s, s);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const darkMetal = new THREE.MeshStandardMaterial({ color: 0x2e3440, roughness: 0.38, metalness: 0.65 });
  const steel = new THREE.MeshStandardMaterial({ color: 0x9aa3ad, roughness: 0.3, metalness: 0.85 });
  const copper = new THREE.MeshStandardMaterial({ color: 0xb87333, roughness: 0.35, metalness: 0.8 });
  const shadeMat = new THREE.MeshStandardMaterial({ color: 0xf5a623, emissive: 0xff9d00, emissiveIntensity: 0.45, roughness: 0.45, metalness: 0.1, side: THREE.DoubleSide });
  const bulbMat = new THREE.MeshStandardMaterial({ color: 0xfff6d5, emissive: 0xffcc66, emissiveIntensity: 2.3, roughness: 0.25, metalness: 0 });
  const beamMat = new THREE.MeshBasicMaterial({ color: 0xffdf99, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
  const poolMat = new THREE.MeshBasicMaterial({ color: 0xffdf8a, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false });
  const poolCoreMat = new THREE.MeshBasicMaterial({ color: 0xfff1b8, transparent: true, opacity: 0.35, blending: THREE.AdditiveBlending, depthWrite: false });
  const switchMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff9d00, emissiveIntensity: 0.5, roughness: 0.4, metalness: 0.2 });
  const ledMat = new THREE.MeshStandardMaterial({ color: 0x22cc66, emissive: 0x22cc66, emissiveIntensity: 1.8, roughness: 0.4 });
  const cordMat = new THREE.MeshStandardMaterial({ color: 0x17191d, roughness: 0.8 });

  function addMesh(mesh, name) {
    mesh.name = name;
    root.add(mesh);
    return mesh;
  }

  function armBetween(x1, y1, z1, x2, y2, z2, radius, material, name) {
    const start = new THREE.Vector3(x1, y1, z1);
    const end = new THREE.Vector3(x2, y2, z2);
    const direction = new THREE.Vector3().subVectors(end, start);
    const length = direction.length();
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, length, 16), material);
    mesh.position.copy(start).add(end).multiplyScalar(0.5);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
    return addMesh(mesh, name);
  }

  // Desk lamp base, centered at the left of the workspace.
  const base = addMesh(new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.068, 0.018, 32), darkMetal), 'LampBase');
  base.position.set(-0.18, 0.009, 0);

  const trim = addMesh(new THREE.Mesh(new THREE.TorusGeometry(0.06, 0.004, 10, 32), steel), 'BaseTrim');
  trim.rotation.x = Math.PI / 2;
  trim.position.set(-0.18, 0.019, 0);

  const stem = addMesh(new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.02, 0.04, 20), darkMetal), 'BaseStem');
  stem.position.set(-0.185, 0.036, 0);

  // Articulated arms.
  armBetween(-0.185, 0.05, 0, -0.165, 0.185, 0, 0.01, steel, 'LowerArm');
  armBetween(-0.165, 0.185, 0, 0.012, 0.272, 0, 0.009, steel, 'UpperArm');

  const lowerJoint = addMesh(new THREE.Mesh(new THREE.SphereGeometry(0.018, 20, 12), copper), 'LowerJoint');
  lowerJoint.position.set(-0.165, 0.185, 0);

  const headJoint = addMesh(new THREE.Mesh(new THREE.SphereGeometry(0.016, 20, 12), copper), 'HeadJoint');
  headJoint.position.set(0.012, 0.272, 0);

  // Shade, bulb and light beam pointing straight down onto the desk.
  const shade = addMesh(new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.06, 0.095, 28, 1, true), shadeMat), 'LampShade');
  shade.position.set(0.04, 0.235, 0);

  const shadeCap = addMesh(new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.028, 0.01, 24), darkMetal), 'ShadeCap');
  shadeCap.position.set(0.04, 0.285, 0);

  const bulbNeck = addMesh(new THREE.Mesh(new THREE.CylinderGeometry(0.01, 0.012, 0.022, 16), steel), 'BulbNeck');
  bulbNeck.position.set(0.04, 0.207, 0);

  const bulb = addMesh(new THREE.Mesh(new THREE.SphereGeometry(0.022, 24, 16), bulbMat), 'Bulb');
  bulb.position.set(0.04, 0.195, 0);

  const beam = addMesh(new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.095, 0.185, 24, 1, true), beamMat), 'LightBeam');
  beam.position.set(0.04, 0.0975, 0);

  const pool = addMesh(new THREE.Mesh(new THREE.CircleGeometry(0.095, 32), poolMat), 'LightPool');
  pool.rotation.x = -Math.PI / 2;
  pool.scale.set(1.25, 1, 1);
  pool.position.set(0.04, 0.003, 0);

  const poolCore = addMesh(new THREE.Mesh(new THREE.CircleGeometry(0.05, 28), poolCoreMat), 'LightPoolCore');
  poolCore.rotation.x = -Math.PI / 2;
  poolCore.scale.set(1.2, 1, 1);
  poolCore.position.set(0.04, 0.004, 0);

  // Round press button on the front of the base and a small status LED.
  const switchButton = addMesh(new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.023, 0.018, 24), switchMat), 'LampSwitch');
  switchButton.position.set(-0.18, 0.024, 0.04);

  const led = addMesh(new THREE.Mesh(new THREE.SphereGeometry(0.009, 16, 10), ledMat), 'StatusLight');
  led.position.set(-0.145, 0.026, 0.048);

  // Power cord trailing behind the lamp.
  const cordCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-0.18, 0.006, -0.06),
    new THREE.Vector3(-0.23, 0.005, -0.12),
    new THREE.Vector3(-0.12, 0.005, -0.18),
    new THREE.Vector3(0.0, 0.005, -0.2),
  ]);
  addMesh(new THREE.Mesh(new THREE.TubeGeometry(cordCurve, 24, 0.004, 8), cordMat), 'PowerCord');

  let isOn = true;
  let level = 1;
  let currentTime = 0;
  let lastToggle = -10;

  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228;
              border-width: 2px; border-color: #3a3f47; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .status { color: #ffd166; font-size: 24px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .hint { color: #aeb6c2; font-size: 22px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk Lamp</span>
      <span class="status" id="status">Lamp is ON</span>
      <span class="body">Press the shade, the bulb or the round button on the base to switch it.</span>
      <span class="hint" id="hint">Warm light is on. Press again to switch off.</span>
      <button class="btn" id="toggle"><span class="btn-text" id="toggleText">Turn off</span></button>
    </div>`, { width: 0.27, position: [0.26, 0.22, 0.03], rotationY: -0.3 });
  root.add(info.object3D);

  function applyState() {
    if (isOn) {
      switchMat.color.setHex(0xffc23d);
      switchMat.emissive.setHex(0xff9d00);
      switchMat.emissiveIntensity = 0.5;
      ledMat.color.setHex(0x22cc66);
      ledMat.emissive.setHex(0x22cc66);
      ledMat.emissiveIntensity = 1.8;
    } else {
      switchMat.color.setHex(0x777777);
      switchMat.emissive.setHex(0x000000);
      switchMat.emissiveIntensity = 0;
      ledMat.color.setHex(0x553333);
      ledMat.emissive.setHex(0x220000);
      ledMat.emissiveIntensity = 0.2;
    }
    info.set('status', { text: isOn ? 'Lamp is ON' : 'Lamp is OFF', color: isOn ? '#ffd166' : '#9aa3ad' });
    info.set('hint', { text: isOn ? 'Warm light is on. Press again to switch off.' : 'Lamp is off. Press the lamp to switch it on.' });
    info.set('toggleText', { text: isOn ? 'Turn off' : 'Turn on' });
  }

  function toggle() {
    isOn = !isOn;
    lastToggle = currentTime;
    applyState();
  }

  info.on('toggle', 'click', toggle);

  // Pressing any of these lamp parts switches the lamp.
  traits(shade, { onPress: toggle });
  traits(bulb, { onPress: toggle });
  traits(switchButton, { onPress: toggle });
  traits(base, { onPress: toggle });

  return {
    root,
    update(time, delta = 0.016) {
      currentTime = time;

      const target = isOn ? 1 : 0;
      level += (target - level) * Math.min(1, delta * 9);
      if (Math.abs(target - level) < 0.001) level = target;

      const flicker = level > 0.05 ? Math.sin(time * 31) * 0.04 * level : 0;
      bulbMat.emissiveIntensity = 0.04 + level * 2.25 + flicker;
      shadeMat.emissiveIntensity = level * 0.45;
      beamMat.opacity = level * 0.16;
      poolMat.opacity = level * (0.5 + Math.sin(time * 2) * 0.02);
      poolCoreMat.opacity = level * 0.35;

      // Brief physical depression of the base button after a press.
      const sinceToggle = time - lastToggle;
      const pressDepth = sinceToggle < 0.18 ? Math.sin((sinceToggle / 0.18) * Math.PI) * 0.005 : 0;
      switchButton.position.y = 0.024 - pressDepth;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Small analog desk clock, centered on its own wooden base.
  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  clock.position.set(-0.14, 0.12, 0);
  root.add(clock);

  const base = new THREE.Mesh(
    new THREE.BoxGeometry(0.24, 0.01, 0.17),
    new THREE.MeshStandardMaterial({ color: 0xa0713f, roughness: 0.7 })
  );
  base.name = 'ClockBase';
  base.position.set(0, -0.11, 0);
  clock.add(base);

  const footGeometry = new THREE.BoxGeometry(0.02, 0.02, 0.04);
  const footMaterial = new THREE.MeshStandardMaterial({ color: 0x14181f, roughness: 0.6 });
  const leftFoot = new THREE.Mesh(footGeometry, footMaterial);
  leftFoot.name = 'ClockFootLeft';
  leftFoot.position.set(-0.06, -0.1, 0);
  clock.add(leftFoot);
  const rightFoot = new THREE.Mesh(footGeometry, footMaterial);
  rightFoot.name = 'ClockFootRight';
  rightFoot.position.set(0.06, -0.1, 0);
  clock.add(rightFoot);

  const caseMesh = new THREE.Mesh(
    new THREE.CylinderGeometry(0.095, 0.095, 0.034, 48),
    new THREE.MeshStandardMaterial({ color: 0x1b2a41, roughness: 0.4, metalness: 0.3 })
  );
  caseMesh.name = 'ClockCase';
  caseMesh.rotation.x = Math.PI / 2;
  clock.add(caseMesh);

  const face = new THREE.Mesh(
    new THREE.CircleGeometry(0.082, 48),
    new THREE.MeshStandardMaterial({ color: 0xf7f3e8, roughness: 0.85 })
  );
  face.name = 'ClockFace';
  face.position.z = 0.018;
  clock.add(face);

  const rim = new THREE.Mesh(
    new THREE.TorusGeometry(0.088, 0.007, 12, 48),
    new THREE.MeshStandardMaterial({ color: 0xc9a24b, roughness: 0.35, metalness: 0.7 })
  );
  rim.name = 'ClockRim';
  rim.position.z = 0.018;
  clock.add(rim);

  // Hour ticks: shorter marks, with longer marks at 12, 3, 6 and 9.
  const shortTickGeometry = new THREE.BoxGeometry(0.0045, 0.012, 0.002);
  const longTickGeometry = new THREE.BoxGeometry(0.007, 0.02, 0.002);
  const tickMaterial = new THREE.MeshStandardMaterial({ color: 0x1d2126, roughness: 0.6 });
  for (let i = 0; i < 12; i++) {
    const angle = i * Math.PI / 6;
    const isLong = i % 3 === 0;
    const tick = new THREE.Mesh(isLong ? longTickGeometry : shortTickGeometry, tickMaterial);
    tick.name = isLong ? 'HourTickLong' : 'HourTick';
    tick.position.set(Math.sin(angle) * 0.068, Math.cos(angle) * 0.068, 0.02);
    tick.rotation.z = -angle;
    clock.add(tick);
  }

  const handMaterial = new THREE.MeshStandardMaterial({ color: 0x1d2126, roughness: 0.5 });
  function makeHand(length, width, material, z, name) {
    const geometry = new THREE.BoxGeometry(width, length, 0.003);
    geometry.translate(0, length / 2 - 0.008, 0);
    const hand = new THREE.Mesh(geometry, material);
    hand.name = name;
    const pivot = new THREE.Group();
    pivot.name = name + 'Pivot';
    pivot.position.z = z;
    pivot.add(hand);
    clock.add(pivot);
    return pivot;
  }

  const hourPivot = makeHand(0.046, 0.009, handMaterial, 0.023, 'HourHand');
  const minutePivot = makeHand(0.068, 0.007, handMaterial, 0.026, 'MinuteHand');
  const secondPivot = makeHand(
    0.073,
    0.0025,
    new THREE.MeshStandardMaterial({ color: 0xd23c2e, emissive: 0x70150d, emissiveIntensity: 0.5, roughness: 0.5 }),
    0.029,
    'SecondHand'
  );

  const cap = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0075, 0.0075, 0.006, 24),
    new THREE.MeshStandardMaterial({ color: 0xc9a24b, roughness: 0.35, metalness: 0.7 })
  );
  cap.name = 'CenterCap';
  cap.rotation.x = Math.PI / 2;
  cap.position.z = 0.03;
  clock.add(cap);

  // Digital readout panel, kept to the side so it never covers the clock face.
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 31px; font-weight: 700; text-align: center; }
      .time { color: #ffffff; font-size: 52px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; text-align: center; }
      .small { color: #aeb6c2; font-size: 20px; text-align: center; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Desk Clock</span>
      <span class="time" id="digital">--:--</span>
      <span class="body" id="dateLine">Loading date</span>
      <span class="small">The analog hands and this digital display show the same current time. Pinch the clock to move it. Press the clock or the button to switch between 12-hour and 24-hour time.</span>
      <button class="btn" id="format"><span class="btn-text" id="formatLabel">Tap for 24-hour time</span></button>
    </div>`, { width: 0.3, position: [0.19, 0.21, 0.02], rotationY: -0.18 });
  root.add(info.object3D);

  const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

  let use24Hour = false;
  let formatDirty = true;
  let lastHour = -1;
  let lastMinute = -1;
  let lastDay = -1;
  let lastMonth = -1;
  const now = new Date();

  function applyTime(d) {
    const hours = d.getHours();
    const minutes = d.getMinutes();
    const seconds = d.getSeconds() + d.getMilliseconds() / 1000;

    const hourAngle = (((hours % 12) + minutes / 60 + seconds / 3600) / 12) * Math.PI * 2;
    const minuteAngle = ((minutes + seconds / 60) / 60) * Math.PI * 2;
    const secondAngle = (seconds / 60) * Math.PI * 2;
    hourPivot.rotation.z = -hourAngle;
    minutePivot.rotation.z = -minuteAngle;
    secondPivot.rotation.z = -secondAngle;

    if (hours !== lastHour || minutes !== lastMinute || formatDirty) {
      formatDirty = false;
      lastHour = hours;
      lastMinute = minutes;

      let displayHour = hours;
      let suffix = '';
      if (!use24Hour) {
        displayHour = hours % 12;
        if (displayHour === 0) displayHour = 12;
        suffix = hours < 12 ? ' AM' : ' PM';
      }
      const minuteText = minutes < 10 ? '0' + minutes : '' + minutes;
      info.set('digital', { text: displayHour + ':' + minuteText + suffix });
      info.set('formatLabel', { text: use24Hour ? 'Tap for 12-hour time' : 'Tap for 24-hour time' });

      const day = d.getDate();
      const month = d.getMonth();
      if (day !== lastDay || month !== lastMonth) {
        lastDay = day;
        lastMonth = month;
        info.set('dateLine', { text: weekdays[d.getDay()] + ', ' + months[month] + ' ' + day + ', ' + d.getFullYear() });
      }
    }
  }

  function toggleFormat() {
    use24Hour = !use24Hour;
    formatDirty = true;
    applyTime(now);
  }

  info.on('format', 'click', toggleFormat);
  traits(clock, { grab: true, onPress: toggleFormat });

  now.setTime(Date.now());
  applyTime(now);

  return {
    root,
    update() {
      // Reuse the same Date object instead of allocating a new one each frame.
      // Hands keep moving even while held; the host moves the clock body itself.
      now.setTime(Date.now());
      applyTime(now);
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const caseMat = new THREE.MeshStandardMaterial({ color: 0x22262b, metalness: 0.35, roughness: 0.45 });
  const faceMat = new THREE.MeshStandardMaterial({ color: 0xf5f1e6, roughness: 0.9 });
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x7a4a2b, roughness: 0.7 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x1a1d22, roughness: 0.6 });
  const numeralMat = new THREE.MeshStandardMaterial({ color: 0x1f3650, roughness: 0.55 });
  const brassMat = new THREE.MeshStandardMaterial({ color: 0xc9a227, metalness: 0.6, roughness: 0.35 });
  const hourMat = new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.5 });
  const minuteMat = new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.5 });
  const secondMat = new THREE.MeshStandardMaterial({ color: 0xd93025, emissive: 0x7a0f08, emissiveIntensity: 0.4, roughness: 0.5 });

  // Clock body, grabbable as a whole.
  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  clock.position.set(-0.15, 0, 0);
  root.add(clock);

  const base = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.016, 0.095), baseMat);
  base.name = 'Base';
  base.position.set(0, 0.008, 0.01);
  clock.add(base);

  const strip = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.003, 0.01), brassMat);
  strip.name = 'BaseTrim';
  strip.position.set(0, 0.017, 0.045);
  clock.add(strip);

  const column = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.13, 0.016), caseMat);
  column.name = 'Stand';
  column.position.set(0, 0.075, -0.028);
  column.rotation.x = -0.18;
  clock.add(column);

  // Tilted dial so it is easy to read from a seated position.
  const dial = new THREE.Group();
  dial.name = 'Dial';
  dial.position.set(0, 0.185, -0.01);
  dial.rotation.x = -0.18;
  clock.add(dial);

  const caseMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.115, 0.115, 0.028, 48), caseMat);
  caseMesh.name = 'Case';
  caseMesh.rotation.x = Math.PI / 2;
  dial.add(caseMesh);

  const face = new THREE.Mesh(new THREE.CylinderGeometry(0.105, 0.105, 0.003, 48), faceMat);
  face.name = 'Face';
  face.rotation.x = Math.PI / 2;
  face.position.z = 0.016;
  dial.add(face);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.108, 0.007, 12, 48), brassMat);
  rim.name = 'Rim';
  rim.position.z = 0.016;
  dial.add(rim);

  const dummy = new THREE.Object3D();

  // 60 minute / hour ticks.
  const ticks = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), darkMat, 60);
  ticks.name = 'Ticks';
  ticks.frustumCulled = false;
  for (let i = 0; i < 60; i++) {
    const angle = (i / 60) * Math.PI * 2;
    const isHour = i % 5 === 0;
    const len = isHour ? 0.014 : 0.007;
    const wid = isHour ? 0.0035 : 0.0018;
    const r = isHour ? 0.094 : 0.0975;
    dummy.position.set(Math.sin(angle) * r, Math.cos(angle) * r, 0.018);
    dummy.rotation.set(0, 0, -angle);
    dummy.scale.set(wid, len, 0.0015);
    dummy.updateMatrix();
    ticks.setMatrixAt(i, dummy.matrix);
  }
  ticks.instanceMatrix.needsUpdate = true;
  dial.add(ticks);

  // Numerals 1 to 12 made from small dot-matrix blocks.
  const DIGITS = {
    '0': ['111', '101', '101', '101', '111'],
    '1': ['010', '110', '010', '010', '111'],
    '2': ['111', '001', '111', '100', '111'],
    '3': ['111', '001', '111', '001', '111'],
    '4': ['101', '101', '111', '001', '001'],
    '5': ['111', '100', '111', '001', '111'],
    '6': ['111', '100', '111', '101', '111'],
    '7': ['111', '001', '010', '010', '010'],
    '8': ['111', '101', '111', '101', '111'],
    '9': ['111', '101', '111', '001', '111']
  };
  const dots = [];
  for (let n = 1; n <= 12; n++) {
    const s = String(n);
    const angle = ((n % 12) / 12) * Math.PI * 2;
    const cx = Math.sin(angle) * 0.07;
    const cy = Math.cos(angle) * 0.07;
    const rot = -angle;
    const cosR = Math.cos(rot);
    const sinR = Math.sin(rot);
    const dot = 0.0032;
    for (let ci = 0; ci < s.length; ci++) {
      const pattern = DIGITS[s[ci]];
      for (let row = 0; row < 5; row++) {
        for (let col = 0; col < 3; col++) {
          if (pattern[row][col] !== '1') continue;
          const lx = (ci - (s.length - 1) / 2) * (3 * dot + 0.004) + (col - 1) * dot;
          const ly = (2 - row) * dot;
          dots.push([cx + lx * cosR - ly * sinR, cy + lx * sinR + ly * cosR]);
        }
      }
    }
  }
  const numerals = new THREE.InstancedMesh(new THREE.BoxGeometry(0.0026, 0.0026, 0.0012), numeralMat, dots.length);
  numerals.name = 'Numerals';
  numerals.frustumCulled = false;
  for (let i = 0; i < dots.length; i++) {
    dummy.position.set(dots[i][0], dots[i][1], 0.018);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    numerals.setMatrixAt(i, dummy.matrix);
  }
  numerals.instanceMatrix.needsUpdate = true;
  dial.add(numerals);

  function makeHand(length, width, tail, mat, name) {
    const shape = new THREE.Shape();
    shape.moveTo(-width / 2, -tail);
    shape.lineTo(width / 2, -tail);
    shape.lineTo(width * 0.18, length * 0.82);
    shape.lineTo(0, length);
    shape.lineTo(-width * 0.18, length * 0.82);
    shape.lineTo(-width / 2, -tail);
    const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.002, bevelEnabled: false });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.name = name;
    const group = new THREE.Group();
    group.add(mesh);
    return group;
  }

  const hourHand = makeHand(0.055, 0.011, 0.015, hourMat, 'HourHand');
  hourHand.name = 'HourHandPivot';
  hourHand.position.z = 0.019;
  dial.add(hourHand);

  const minuteHand = makeHand(0.085, 0.008, 0.015, minuteMat, 'MinuteHand');
  minuteHand.name = 'MinuteHandPivot';
  minuteHand.position.z = 0.022;
  dial.add(minuteHand);

  const secondHand = makeHand(0.088, 0.003, 0.02, secondMat, 'SecondHand');
  secondHand.name = 'SecondHandPivot';
  secondHand.position.z = 0.025;
  const counter = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.002, 20), secondMat);
  counter.rotation.x = Math.PI / 2;
  counter.position.set(0, -0.015, 0.001);
  secondHand.add(counter);
  dial.add(secondHand);

  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.0075, 0.0075, 0.004, 24), brassMat);
  cap.name = 'CenterCap';
  cap.rotation.x = Math.PI / 2;
  cap.position.z = 0.026;
  dial.add(cap);

  // Two small winding knobs on top of the case.
  for (let i = -1; i <= 1; i += 2) {
    const knob = new THREE.Mesh(new THREE.CylinderGeometry(0.009, 0.009, 0.014, 20), brassMat);
    knob.name = 'Knob';
    knob.position.set(i * 0.05, 0.119, 0);
    dial.add(knob);
  }

  traits(clock, { grab: true });

  const panel = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; border-width: 2px; border-color: #3a3f47; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .time { color: #ffd166; font-size: 46px; font-weight: 700; text-align: center; }
      .date { color: #aeb6c2; font-size: 20px; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; justify-content: center; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; border-width: 0px; border-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk clock</span>
      <span class="time" id="digital">--:--</span>
      <span class="date" id="dateLine">Loading date</span>
      <span class="body">The short hand shows hours and the long hand shows minutes. Pinch the clock to move it.</span>
      <div class="row">
        <button class="btn" id="formatBtn"><span class="btn-text" id="formatLabel">24-hour</span></button>
        <button class="btn" id="secondBtn"><span class="btn-text" id="secondLabel">Hide seconds</span></button>
      </div>
    </div>`, { width: 0.32, position: [0.21, 0.19, 0.03], rotationY: -0.18 });
  root.add(panel.object3D);

  let use24 = false;
  let showSeconds = true;
  let lastDigital = '';
  let lastDate = '';

  panel.on('formatBtn', 'click', () => {
    use24 = !use24;
    panel.set('formatLabel', { text: use24 ? '12-hour' : '24-hour' });
    lastDigital = '';
  });
  panel.on('secondBtn', 'click', () => {
    showSeconds = !showSeconds;
    secondHand.visible = showSeconds;
    panel.set('secondLabel', { text: showSeconds ? 'Hide seconds' : 'Show seconds' });
  });

  const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const now = new Date();

  return {
    root,
    update() {
      now.setTime(Date.now());
      const seconds = now.getSeconds() + now.getMilliseconds() / 1000;
      const minutesFloat = now.getMinutes() + seconds / 60;
      const hoursFloat = (now.getHours() % 12) + minutesFloat / 60;

      hourHand.rotation.z = -(hoursFloat / 12) * Math.PI * 2;
      minuteHand.rotation.z = -(minutesFloat / 60) * Math.PI * 2;
      secondHand.rotation.z = -(seconds / 60) * Math.PI * 2;

      const h = now.getHours();
      const m = now.getMinutes();
      const mm = m < 10 ? '0' + m : String(m);
      let digital;
      if (use24) {
        digital = (h < 10 ? '0' + h : String(h)) + ':' + mm;
      } else {
        const h12 = h % 12 === 0 ? 12 : h % 12;
        digital = h12 + ':' + mm + (h < 12 ? ' AM' : ' PM');
      }
      if (digital !== lastDigital) {
        panel.set('digital', { text: digital });
        lastDigital = digital;
      }

      const dateText = DAYS[now.getDay()] + ', ' + now.getDate() + ' ' + MONTHS[now.getMonth()] + ' ' + now.getFullYear();
      if (dateText !== lastDate) {
        panel.set('dateLine', { text: dateText });
        lastDate = dateText;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  let info = null;
  let level = 0;
  let lastOnLevel = 2;
  let target = 0;
  let current = 0;

  function updatePanel() {
    if (!info) return;
    if (level === 0) {
      info.set('status', { text: 'OFF - Press the lamp to switch it on.' });
      info.set('dot', { backgroundColor: '#8a919c' });
    } else if (level === 1) {
      info.set('status', { text: 'ON - Low brightness. Press the lamp to switch it off.' });
      info.set('dot', { backgroundColor: '#ffb84d' });
    } else {
      info.set('status', { text: 'ON - High brightness. Press the lamp to switch it off.' });
      info.set('dot', { backgroundColor: '#7dff8a' });
    }
  }

  function setLevel(next) {
    level = next;
    target = next === 0 ? 0 : (next === 1 ? 0.45 : 1);
    if (next > 0) lastOnLevel = next;
    updatePanel();
  }

  function toggleLamp() {
    if (level === 0) setLevel(lastOnLevel);
    else setLevel(0);
  }

  const metalMat = new THREE.MeshStandardMaterial({ color: 0x3b4148, metalness: 0.65, roughness: 0.38 });
  const shadeMat = new THREE.MeshStandardMaterial({
    color: 0x26515e, metalness: 0.35, roughness: 0.45,
    emissive: 0xffc978, emissiveIntensity: 0, side: THREE.DoubleSide
  });
  const bulbMat = new THREE.MeshStandardMaterial({
    color: 0xfff2c0, roughness: 0.35, emissive: 0xffc978, emissiveIntensity: 0
  });
