      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; border-width: 0px; border-color: #2f6fdb; }
      .btn-alt { background-color: #39404a; border-color: #39404a; }
      .btn-label { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="header"><div class="dot" id="dot"></div><span class="title">Desk Lamp</span></div>
      <span class="body" id="status">OFF - Press the lamp to switch it on.</span>
      <span class="hint">Press the shade, the bulb or the orange button on the base.</span>
      <div class="row">
        <button class="btn" id="turnOn"><span class="btn-label">Turn on</span></button>
        <button class="btn btn-alt" id="turnOff"><span class="btn-label">Turn off</span></button>
        <button class="btn btn-alt" id="bright"><span class="btn-label">Brightness</span></button>
      </div>
    </div>`, { width: 0.28, position: [0.26, 0.24, 0.04], rotationY: -0.15 });
  root.add(info.object3D);

  info.on('turnOn', 'click', () => setLevel(2));
  info.on('turnOff', 'click', () => setLevel(0));
  info.on('bright', 'click', () => {
    if (level === 0) setLevel(2);
    else if (level === 2) setLevel(1);
    else setLevel(2);
  });

  return {
    root,
    update(time, delta) {
      const dt = delta === undefined ? 0.016 : Math.min(delta, 0.05);
      const k = Math.min(1, dt * 9);
      current += (target - current) * k;
      if (Math.abs(target - current) < 0.001) current = target;

      bulbMat.emissiveIntensity = current * 2.6;
      shadeMat.emissiveIntensity = current * 0.5;
      coneMat.opacity = current * 0.15;
      spotMat.opacity = current * 0.5;
      buttonMat.emissiveIntensity = 0.12 + current * 1.0;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  let playing = true;
  let selectedKey = 'overview';
  let stepIndex = 0;

  // ----- base tray -----
  const tray = new THREE.Mesh(
