  // ----- pot and soil -----
  const potGroup = new THREE.Group();
  potGroup.name = 'Pot and roots';
  potGroup.position.set(-0.05, 0, 0);
  root.add(potGroup);

  const pot = new THREE.Mesh(
    new THREE.CylinderGeometry(0.058, 0.044, 0.075, 24),
