  );
  pot.position.set(0, 0.0525, 0);
  potGroup.add(pot);

  const rim = new THREE.Mesh(
    new THREE.CylinderGeometry(0.062, 0.062, 0.014, 24),
    new THREE.MeshStandardMaterial({ color: 0x9e4b28, roughness: 0.8 })
  );
  rim.position.set(0, 0.088, 0);
  potGroup.add(rim);

  const soil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.053, 0.053, 0.012, 24),
    new THREE.MeshStandardMaterial({ color: 0x3e2f22, roughness: 1.0 })
  );
  soil.position.set(0, 0.092, 0);
  potGroup.add(soil);

  // ----- plant canopy (stem and leaves) -----
  const canopy = new THREE.Group();
  canopy.name = 'Leaves';
  canopy.position.set(-0.05, 0.095, 0);
  root.add(canopy);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.006, 0.008, 0.14, 10),
    new THREE.MeshStandardMaterial({ color: 0x2e7d32, roughness: 0.6 })
  );
  stem.position.set(0, 0.07, 0);
  stem.rotation.z = 0.06;
  canopy.add(stem);

  const leafGeo = new THREE.SphereGeometry(0.038, 20, 12);
  const leafMatA = new THREE.MeshStandardMaterial({ color: 0x43a047, roughness: 0.55 });
  const leafMatB = new THREE.MeshStandardMaterial({ color: 0x2e7d32, roughness: 0.55 });

  const leafDefs = [
    { pos: [0.045, 0.14, 0.0], rot: [0, 0.3, -0.4], mat: leafMatA },
    { pos: [-0.045, 0.15, 0.01], rot: [0.1, -0.4, 0.45], mat: leafMatB },
    { pos: [0.0, 0.17, 0.03], rot: [0.4, 0.1, 0.15], mat: leafMatA },
    { pos: [0.02, 0.12, -0.035], rot: [-0.3, 0.5, -0.2], mat: leafMatB },
    { pos: [-0.02, 0.19, -0.01], rot: [0.1, 0.2, 0.25], mat: leafMatA },
  ];
  for (const d of leafDefs) {
    const leaf = new THREE.Mesh(leafGeo, d.mat);
    leaf.name = 'Leaf';
    leaf.position.set(d.pos[0], d.pos[1], d.pos[2]);
    leaf.rotation.set(d.rot[0], d.rot[1], d.rot[2]);
    leaf.scale.set(1.25, 0.28, 0.6);
    canopy.add(leaf);
  }

  // ----- sun -----
  const sunGroup = new THREE.Group();
  sunGroup.name = 'Sun';
  sunGroup.position.set(-0.29, 0.39, -0.09);
  root.add(sunGroup);

  const sunMat = new THREE.MeshStandardMaterial({
    color: 0xffd23f, emissive: 0xff8a00, emissiveIntensity: 0.85, roughness: 0.4,
  });
  const sunMesh = new THREE.Mesh(new THREE.SphereGeometry(0.042, 24, 12), sunMat);
  sunMesh.name = 'Sun';
  sunGroup.add(sunMesh);

  const sunRing = new THREE.Mesh(
    new THREE.TorusGeometry(0.058, 0.004, 10, 40),
    new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff8a00, emissiveIntensity: 0.7 })
  );
  sunGroup.add(sunRing);

  const rayGeo = new THREE.BoxGeometry(0.028, 0.008, 0.008);
  const rayMat = new THREE.MeshStandardMaterial({
    color: 0xffd23f, emissive: 0xff8a00, emissiveIntensity: 0.6,
  });
  for (let i = 0; i < 6; i++) {
    const a = (i * Math.PI) / 3;
    const ray = new THREE.Mesh(rayGeo, rayMat);
    ray.position.set(Math.cos(a) * 0.068, Math.sin(a) * 0.068, 0);
    ray.rotation.z = a;
    sunGroup.add(ray);
  }

  // ----- grabbable water droplet -----
  const dropletGroup = new THREE.Group();
  dropletGroup.name = 'Water drop';
  dropletGroup.position.set(-0.205, 0.033, 0.10);
  root.add(dropletGroup);

  const dropMat = new THREE.MeshStandardMaterial({
    color: 0x3fa7ff, emissive: 0x1a5fb4, emissiveIntensity: 0.4, roughness: 0.2,
  });
  const dropMesh = new THREE.Mesh(new THREE.SphereGeometry(0.013, 18, 12), dropMat);
  dropMesh.scale.set(1, 1.35, 1);
  dropletGroup.add(dropMesh);
  const dropTip = new THREE.Mesh(new THREE.ConeGeometry(0.007, 0.013, 12), dropMat);
  dropTip.position.set(0, 0.02, 0);
  dropletGroup.add(dropTip);

  // ----- labeled arrows -----
  const arrows = [];
  const particleGeo = new THREE.SphereGeometry(0.008, 12, 8);

  function makeArrow(key, label, startArr, endArr, color, speed) {
    const start = new THREE.Vector3(startArr[0], startArr[1], startArr[2]);
    const end = new THREE.Vector3(endArr[0], endArr[1], endArr[2]);
    const dir = end.clone().sub(start);
    const len = dir.length();
    const dirN = dir.clone().normalize();

    const group = new THREE.Group();
    group.name = label + ' arrow';
    group.position.copy(start);
    group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dirN);

    const mat = new THREE.MeshStandardMaterial({
      color, emissive: color, emissiveIntensity: 0.35, roughness: 0.35,
    });

    const shaftLen = len * 0.66;
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, shaftLen, 10), mat);
    shaft.position.set(0, shaftLen / 2, 0);
    group.add(shaft);

    const head = new THREE.Mesh(new THREE.ConeGeometry(0.017, 0.04, 16), mat);
    head.position.set(0, shaftLen + 0.018, 0);
    group.add(head);

    const particleMat = new THREE.MeshBasicMaterial({ color });
    const particles = [];
    for (let i = 0; i < 3; i++) {
      const p = new THREE.Mesh(particleGeo, particleMat);
      p.position.set(0, 0.02, 0);
      group.add(p);
      particles.push({ mesh: p, offset: i / 3 });
    }

    root.add(group);
    const entry = { key, group, mat, particles, len, speed, phase: 0, scaleCur: 1 };
    arrows.push(entry);
    return entry;
  }

  makeArrow('light', 'Light', [-0.25, 0.36, -0.08], [-0.11, 0.25, -0.01], 0xffd23f, 0.45);
  makeArrow('water', 'Water', [-0.16, 0.025, 0.08], [-0.08, 0.09, 0.035], 0x3fa7ff, 0.30);
  makeArrow('co2', 'Carbon dioxide', [0.11, 0.26, -0.04], [0.03, 0.24, 0.0], 0xc0c8d0, 0.35);
  makeArrow('oxygen', 'Oxygen', [0.0, 0.27, 0.01], [0.10, 0.37, 0.04], 0xff6b4a, 0.40);

  // ----- arrow labels -----
  const labelHandles = [];
  function makeLabel(key, text, border, position) {
    const h = ui(`
      <style>
        .lbl { width: 200px; flex-direction: column; align-items: center;
               padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px;
               border-radius: 12px; background-color: #23262c; border-width: 2px; border-color: ${border}; }
        .txt { color: #ffffff; font-size: 28px; font-weight: 700; }
      </style>
      <div class="lbl"><span class="txt" id="t">${text}</span></div>`,
      { width: 0.10, position, rotationY: 0 });
    root.add(h.object3D);
    labelHandles.push({ key, handle: h });
    return h;
  }

  makeLabel('light', 'Light', '#ffd23f', [-0.26, 0.285, 0.06]);
  makeLabel('water', 'Water', '#3fa7ff', [-0.21, 0.075, 0.12]);
  makeLabel('co2', 'CO2 in', '#c0c8d0', [0.06, 0.285, 0.07]);
  makeLabel('oxygen', 'Oxygen', '#ff6b4a', [0.06, 0.39, 0.09]);

  // ----- main info panel -----
  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 10px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; background-color: #1f2228; border-width: 2px; border-color: #3a3f47; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .eq { color: #ffd23f; font-size: 24px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 23px; }
      .hint { color: #9aa3b0; font-size: 23px; }
      .row { flex-direction: row; gap: 10px; align-items: center; justify-content: flex-start; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; border-width: 2px; border-color: #2f6fdb; }
      .btnAlt { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #3a3f47; border-width: 2px; border-color: #3a3f47; }
      .btnText { color: #ffffff; font-size: 23px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title" id="title">Photosynthesis</span>
      <span class="eq">Sunlight + Water + CO2 -> Glucose + Oxygen</span>
      <span class="body" id="body">A plant uses sunlight, water and carbon dioxide to make glucose for food. Oxygen is released into the air as a by-product.</span>
      <span class="hint">Press an arrow, the Sun or a leaf.</span>
      <div class="row">
        <button class="btnAlt" id="prev"><span class="btnText">Back</span></button>
        <button class="btn" id="next"><span class="btnText">Next</span></button>
        <button class="btn" id="play"><span class="btnText" id="playText">Pause flow</span></button>
      </div>
    </div>`,
    { width: 0.26, position: [0.27, 0.24, 0.06], rotationY: -0.25 });
  root.add(info.object3D);

  // ----- content and selection -----
  const ORDER = ['overview', 'light', 'water', 'co2', 'oxygen'];
  const CONTENT = {
    overview: {
      title: 'Photosynthesis',
      body: 'A plant uses sunlight, water and carbon dioxide to make glucose for food. Oxygen is released into the air as a by-product.',
    },
    light: {
      title: '1 - Light in',
      body: 'Sunlight is captured by chlorophyll, the green pigment in the leaves. Its energy powers the chemical reaction.',
    },
    water: {
      title: '2 - Water in',
      body: 'Roots absorb water from the soil. Water travels up the stem to the leaves, where it is split during the reaction.',
    },
    co2: {
      title: '3 - Carbon dioxide in',
      body: 'Leaves take in carbon dioxide from the air through tiny pores called stomata. The carbon in it becomes part of the glucose.',
    },
    oxygen: {
      title: '4 - Oxygen out',
      body: 'Oxygen is released from the leaves into the air. Most of this oxygen comes from water molecules that were split.',
    },
    plant: {
      title: 'Leaves',
      body: 'Leaves are the main site of photosynthesis. They contain chloroplasts, and inside them chlorophyll gives leaves their green color.',
    },
  };

  function select(key) {
    selectedKey = key;
    const idx = ORDER.indexOf(key);
    if (idx >= 0) stepIndex = idx;
    const c = CONTENT[key];
    info.set('title', { text: c.title });
    info.set('body', { text: c.body });
    for (const a of arrows) {
      a.mat.emissiveIntensity = a.key === key ? 0.95 : 0.3;
    }
    sunMat.emissiveIntensity = key === 'light' ? 1.4 : 0.85;
    for (const l of labelHandles) {
      l.handle.set('t', { color: l.key === key ? '#ffd23f' : '#ffffff' });
    }
  }

  // ----- interactions -----
  traits(sunGroup, { onPress: () => select('light') });
  traits(canopy, { onPress: () => select('plant') });
  traits(potGroup, { onPress: () => select('water') });
  traits(dropletGroup, { grab: true, onPress: () => select('water') });
  for (const a of arrows) {
    traits(a.group, { onPress: () => select(a.key) });
  }

  info.on('next', 'click', () => {
    stepIndex = (stepIndex + 1) % ORDER.length;
    select(ORDER[stepIndex]);
  });
  info.on('prev', 'click', () => {
    stepIndex = (stepIndex - 1 + ORDER.length) % ORDER.length;
    select(ORDER[stepIndex]);
  });
  info.on('play', 'click', () => {
    playing = !playing;
    info.set('playText', { text: playing ? 'Pause flow' : 'Play flow' });
  });

  select('overview');

  return {
    root,
    update(time, delta) {
      if (playing) {
        sunRing.rotation.z = time * 0.4;
        sunMesh.scale.setScalar(1 + Math.sin(time * 2.2) * 0.06);
      } else {
        sunMesh.scale.setScalar(1);
      }

      canopy.rotation.z = Math.sin(time * 0.9) * 0.035;
      canopy.rotation.x = Math.sin(time * 0.6) * 0.015;

      for (const a of arrows) {
        if (playing) a.phase = (a.phase + delta * a.speed) % 1;
        for (const p of a.particles) {
          const t = (a.phase + p.offset) % 1;
          p.mesh.position.set(0, 0.012 + t * (a.len - 0.024), 0);
        }
        const target = a.key === selectedKey ? 1.16 : 1.0;
        a.scaleCur += (target - a.scaleCur) * Math.min(1, delta * 8);
        a.group.scale.setScalar(a.scaleCur);
      }

      if (!isGrabbed(dropletGroup)) {
        dropMesh.position.y = Math.sin(time * 1.6) * 0.003;
        dropTip.position.y = 0.02 + Math.sin(time * 1.6) * 0.003;
      }
    },
  };
}

