    new THREE.CylinderGeometry(0.044, 0.044, 0.01, 20),
    new THREE.MeshStandardMaterial({ color: 0x4a3428, roughness: 1.0 })
  );
  soil.name = 'Soil';
  soil.position.y = 0.072;
  plantGroup.add(soil);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.006, 0.008, 0.19, 10),
    new THREE.MeshStandardMaterial({ color: 0x2e7d32, roughness: 0.7 })
  );
  stem.name = 'Stem';
  stem.position.y = 0.165;
  plantGroup.add(stem);

  const leafMat = new THREE.MeshStandardMaterial({ color: 0x43a047, roughness: 0.6 });
  const leafMat2 = new THREE.MeshStandardMaterial({ color: 0x66bb6a, roughness: 0.6 });
  const leafGeo = new THREE.SphereGeometry(0.032, 20, 12);
  const leafSpecs = [
    { p: [-0.045, 0.19, 0.015], ry: 0.6, rz: 0.45, mat: leafMat },
    { p: [0.045, 0.22, -0.01], ry: -0.5, rz: -0.35, mat: leafMat2 },
    { p: [-0.015, 0.255, 0.02], ry: 0.2, rz: 0.15, mat: leafMat },
    { p: [0.015, 0.17, 0.035], ry: 1.1, rz: -0.6, mat: leafMat2 }
  ];
  for (let i = 0; i < leafSpecs.length; i++) {
    const spec = leafSpecs[i];
    const leaf = new THREE.Mesh(leafGeo, spec.mat);
    leaf.name = 'Leaf';
    leaf.position.set(spec.p[0], spec.p[1], spec.p[2]);
    leaf.scale.set(1.5, 0.35, 0.75);
    leaf.rotation.set(0, spec.ry, spec.rz);
    plantGroup.add(leaf);
  }

  const sugarDots = [];
  const sugarMat = new THREE.MeshStandardMaterial({ color: 0xffb347, emissive: 0xff8a00, emissiveIntensity: 0.5, roughness: 0.4 });
  const sugarGeo = new THREE.SphereGeometry(0.012, 16, 12);
  const sugarSpecs = [[-0.05, 0.20, 0.03], [0.05, 0.24, 0.02], [0.01, 0.285, 0.04]];
  for (let i = 0; i < sugarSpecs.length; i++) {
    const dot = new THREE.Mesh(sugarGeo, sugarMat);
    dot.name = 'Glucose sugar';
    dot.position.set(sugarSpecs[i][0], sugarSpecs[i][1], sugarSpecs[i][2]);
    dot.visible = false;
    plantGroup.add(dot);
    sugarDots.push(dot);
  }

  const waterGroup = new THREE.Group();
  waterGroup.name = 'Water source';
  waterGroup.position.set(-0.30, 0, 0.12);
  root.add(waterGroup);
  const puddle = new THREE.Mesh(
    new THREE.CylinderGeometry(0.04, 0.04, 0.01, 20),
    new THREE.MeshStandardMaterial({ color: 0x3a86d6, roughness: 0.3, transparent: true, opacity: 0.85 })
  );
  puddle.name = 'Water puddle';
  puddle.position.y = 0.016;
  waterGroup.add(puddle);
  const droplet = new THREE.Mesh(
    new THREE.SphereGeometry(0.022, 18, 12),
    new THREE.MeshStandardMaterial({ color: 0x4aa3f0, emissive: 0x1a5fb0, emissiveIntensity: 0.5, roughness: 0.3 })
  );
  droplet.name = 'Water droplet';
  droplet.scale.set(1, 1.35, 1);
  droplet.position.y = 0.05;
  waterGroup.add(droplet);

  const co2Group = new THREE.Group();
  co2Group.name = 'CO2 in air';
  co2Group.position.set(0.25, 0.295, -0.06);
  root.add(co2Group);
  const co2Mat = new THREE.MeshStandardMaterial({ color: 0xdfe3e8, roughness: 0.5 });
  const co2Specs = [[0, 0, 0, 0.019], [0.032, 0.016, 0.01, 0.016], [-0.028, -0.012, 0.016, 0.017]];
  for (let i = 0; i < co2Specs.length; i++) {
    const s = co2Specs[i];
    const m = new THREE.Mesh(new THREE.SphereGeometry(s[3], 16, 12), co2Mat);
    m.name = 'CO2 molecule';
    m.position.set(s[0], s[1], s[2]);
    co2Group.add(m);
  }

  const o2Group = new THREE.Group();
  o2Group.name = 'Oxygen bubbles';
  o2Group.position.set(0.15, 0.36, 0.03);
  root.add(o2Group);
  const o2Mat = new THREE.MeshStandardMaterial({ color: 0x9be8a8, roughness: 0.35, transparent: true, opacity: 0.85 });
  const o2Specs = [[0, 0, 0, 0.018], [0.026, 0.02, -0.005, 0.014], [-0.022, 0.018, 0.01, 0.015]];
  for (let i = 0; i < o2Specs.length; i++) {
    const s = o2Specs[i];
    const m = new THREE.Mesh(new THREE.SphereGeometry(s[3], 16, 12), o2Mat);
    m.name = 'Oxygen bubble';
    m.position.set(s[0], s[1], s[2]);
    o2Group.add(m);
  }

  function makeArrow(start, end, color, name) {
    const group = new THREE.Group();
    group.name = name;
    const mat = new THREE.MeshStandardMaterial({ color: color, emissive: color, emissiveIntensity: 0.35, roughness: 0.4 });
    const delta = new THREE.Vector3().subVectors(end, start);
    const len = delta.length();
    const n = delta.normalize();
    const shaftLen = len * 0.72;
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.011, 0.011, shaftLen, 12), mat);
    shaft.name = name + ' shaft';
    shaft.quaternion.setFromUnitVectors(up, n);
    shaft.position.copy(start).addScaledVector(n, shaftLen * 0.5);
    const headLen = 0.045;
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.024, headLen, 16), mat);
    head.name = name + ' head';
    head.quaternion.setFromUnitVectors(up, n);
    head.position.copy(start).addScaledVector(n, len - headLen * 0.5);
    group.add(shaft);
    group.add(head);
    root.add(group);
    return { group: group, mat: mat };
  }

  const arrowDefs = [
    { start: new THREE.Vector3(-0.205, 0.33, -0.105), end: new THREE.Vector3(-0.095, 0.225, 0.03), color: 0xffd23f, name: 'Light arrow' },
    { start: new THREE.Vector3(-0.26, 0.035, 0.11), end: new THREE.Vector3(-0.135, 0.075, 0.045), color: 0x3a86d6, name: 'Water arrow' },
    { start: new THREE.Vector3(0.20, 0.305, -0.04), end: new THREE.Vector3(-0.01, 0.25, 0.02), color: 0xdfe3e8, name: 'CO2 arrow' },
    { start: new THREE.Vector3(-0.035, 0.285, 0.04), end: new THREE.Vector3(0.13, 0.355, 0.035), color: 0x66d97a, name: 'Oxygen arrow' }
  ];
  const arrowGroups = [];
  const arrowMats = [];
  for (let i = 0; i < arrowDefs.length; i++) {
    const d = arrowDefs[i];
    const a = makeArrow(d.start, d.end, d.color, d.name);
    arrowGroups.push(a.group);
    arrowMats.push(a.mat);
  }

  const particles = [];
  const particleGeo = new THREE.SphereGeometry(0.0085, 12, 8);
  const lightPtMat = new THREE.MeshStandardMaterial({ color: 0xffd23f, emissive: 0xffb000, emissiveIntensity: 0.9 });
  const waterPtMat = new THREE.MeshStandardMaterial({ color: 0x6ab8ff, emissive: 0x1a5fb0, emissiveIntensity: 0.6 });
  const co2PtMat = new THREE.MeshStandardMaterial({ color: 0xe8ecf1, roughness: 0.5 });
  const o2PtMat = new THREE.MeshStandardMaterial({ color: 0x8ef0a0, emissive: 0x2e8b40, emissiveIntensity: 0.5 });

  function addParticles(start, end, material, rate, isLight, label) {
    for (let i = 0; i < 3; i++) {
      const mesh = new THREE.Mesh(particleGeo, material);
      mesh.name = label;
      root.add(mesh);
      particles.push({ mesh: mesh, start: start.clone(), end: end.clone(), t: i / 3, rate: rate, isLight: isLight });
    }
  }

  addParticles(new THREE.Vector3(-0.26, 0.36, -0.14), new THREE.Vector3(-0.095, 0.225, 0.03), lightPtMat, 0.28, true, 'Light particle');
  addParticles(new THREE.Vector3(-0.26, 0.035, 0.11), new THREE.Vector3(-0.135, 0.075, 0.045), waterPtMat, 0.22, false, 'Water particle');
  addParticles(new THREE.Vector3(0.20, 0.305, -0.04), new THREE.Vector3(-0.01, 0.25, 0.02), co2PtMat, 0.22, false, 'CO2 particle');
  addParticles(new THREE.Vector3(-0.035, 0.285, 0.04), new THREE.Vector3(0.15, 0.36, 0.03), o2PtMat, 0.28, false, 'Oxygen particle');

  traits(sunGroup, { grab: true, onPress: () => setStep(1) });
  traits(plantGroup, { onPress: () => setStep(0) });
  traits(waterGroup, { onPress: () => setStep(2) });
  traits(co2Group, { onPress: () => setStep(3) });
  traits(o2Group, { onPress: () => setStep(4) });
  traits(arrowGroups[0], { onPress: () => setStep(1) });
  traits(arrowGroups[1], { onPress: () => setStep(2) });
  traits(arrowGroups[2], { onPress: () => setStep(3) });
  traits(arrowGroups[3], { onPress: () => setStep(4) });

  return {
    root,
    update(time, delta) {
      if (!isGrabbed(sunGroup)) {
        sunGroup.rotation.z = time * 0.15;
      }
      plantGroup.rotation.z = Math.sin(time * 0.9) * 0.02;
      droplet.scale.y = 1.35 + Math.sin(time * 2.2) * 0.12;

      const co2TargetX = current === 3 ? 0.215 : 0.25;
      co2Group.position.x += (co2TargetX - co2Group.position.x) * Math.min(1, delta * 3);
      const o2TargetY = current === 4 ? 0.395 : 0.36;
      o2Group.position.y += (o2TargetY - o2Group.position.y) * Math.min(1, delta * 3);

      for (let i = 0; i < sugarDots.length; i++) {
        sugarDots[i].visible = current === 4;
      }
      for (let i = 0; i < arrowMats.length; i++) {
        arrowMats[i].emissiveIntensity = i === selectedArrow ? 0.85 + 0.3 * Math.sin(time * 5) : 0.35;
      }
      if (animOn) {
        for (let i = 0; i < particles.length; i++) {
          const p = particles[i];
          p.t += delta * p.rate;
          if (p.t >= 1) p.t -= 1;
        }
      }
      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        if (p.isLight) p.start.copy(sunGroup.position);
        p.mesh.position.copy(p.start).lerp(p.end, p.t);
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const DEG = Math.PI / 180;
  const center = new THREE.Vector3(-0.13, 0.205, -0.04);

  const earth = new THREE.Group();
  earth.position.copy(center);
  root.add(earth);

  function markerLocal(angleDeg, r) {
    const angle = angleDeg * DEG;
    const s = r * Math.cos(angle);
    const y = r * Math.sin(angle);
    return new THREE.Vector3(s * 0.70710678 - 0.005656, y, s * 0.70710678 + 0.005656);
  }

  const layers = [
    {
      id: 'crust', name: 'Crust', ringInner: 0.14, ringOuter: 0.155,
      color: 0x9c7c4f, cssColor: '#9c7c4f', emissive: 0x4a3a20, metalness: 0.0, roughness: 0.9,
      detail: '0 to 70 km - solid rock',
      fact: 'Crust: the thinnest layer (0 to 70 km). Solid rock, and this is where we live.',
      markerAngle: 50, markerR: 0.1475
    },
    {
      id: 'mantle', name: 'Mantle', ringInner: 0.09, ringOuter: 0.14,
      color: 0xe85d26, cssColor: '#e85d26', emissive: 0x662200, metalness: 0.1, roughness: 0.65,
      detail: '70 to 2,900 km - flowing rock',
      fact: 'Mantle: 70 to 2,900 km deep. Hot rock flows very slowly and moves the plates.',
      markerAngle: 20, markerR: 0.115
    },
    {
      id: 'outer', name: 'Outer core', ringInner: 0.05, ringOuter: 0.09,
      color: 0xf0a830, cssColor: '#f0a830', emissive: 0x774400, metalness: 0.4, roughness: 0.35,
      detail: '2,900 to 5,150 km - liquid metal',
      fact: 'Outer core: 2,900 to 5,150 km deep. Liquid iron and nickel. Its flow makes the magnetic field.',
      markerAngle: -30, markerR: 0.07
    },
    {
      id: 'inner', name: 'Inner core', ringInner: 0.0, ringOuter: 0.05,
      color: 0xf7d54d, cssColor: '#f7d54d', emissive: 0x8a6d00, metalness: 0.5, roughness: 0.3,
      detail: '5,150 to 6,371 km - solid metal',
      fact: 'Inner core: 5,150 to 6,371 km deep. Solid iron and nickel, held solid by great pressure.',
      markerAngle: -65, markerR: 0.035
    }
  ];

  layers.forEach((layer) => {
    layer.material = new THREE.MeshStandardMaterial({
      color: layer.color,
      roughness: layer.roughness,
      metalness: layer.metalness,
      emissive: layer.emissive,
      emissiveIntensity: 0.12,
      side: THREE.DoubleSide
    });
    layer.markerLocal = markerLocal(layer.markerAngle, layer.markerR);
  });

  const phiStart = 3 * Math.PI / 4;
  const phiLength = 3 * Math.PI / 2;

  layers.forEach((layer) => {
    const geo = new THREE.SphereGeometry(layer.ringOuter, 48, 32, phiStart, phiLength);
    const mesh = new THREE.Mesh(geo, layer.material);
    mesh.name = layer.name + ' shell';
    earth.add(mesh);
  });

  function makeHalfAnnulus(outer, inner) {
    const shape = new THREE.Shape();
    if (inner <= 0.0001) {
      shape.moveTo(0, -outer);
      shape.absarc(0, 0, outer, -Math.PI / 2, Math.PI / 2, false);
      shape.lineTo(0, -outer);
    } else {
      shape.moveTo(0, -outer);
      shape.absarc(0, 0, outer, -Math.PI / 2, Math.PI / 2, false);
      shape.lineTo(0, inner);
      shape.absarc(0, 0, inner, Math.PI / 2, -Math.PI / 2, true);
      shape.lineTo(0, -outer);
    }
    return shape;
  }

  const faceConfigs = [
    { rotationY: -Math.PI / 4, offset: 0.0007 },
    { rotationY: -3 * Math.PI / 4, offset: -0.0007 }
  ];

  faceConfigs.forEach((face, faceIndex) => {
    const group = new THREE.Group();
    group.rotation.y = face.rotationY;
    earth.add(group);
    layers.forEach((layer) => {
      const shape = makeHalfAnnulus(layer.ringOuter, layer.ringInner);
      const geo = new THREE.ShapeGeometry(shape, 24);
      const mesh = new THREE.Mesh(geo, layer.material);
      mesh.position.z = face.offset;
      mesh.name = layer.name + ' cut face ' + (faceIndex + 1);
      group.add(mesh);
    });
  });

  function addPatch(phiDeg, thetaDeg, phiLenDeg, thetaLenDeg, color, name, radius) {
    const geo = new THREE.SphereGeometry(radius, 24, 12, phiDeg * DEG, phiLenDeg * DEG, thetaDeg * DEG, thetaLenDeg * DEG);
    const mat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.8, metalness: 0.0 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.name = name;
    earth.add(mesh);
  }

  addPatch(175, 58, 85, 62, 0x3b7dc4, 'Ocean patch', 0.1563);
  addPatch(285, 65, 45, 45, 0x679b47, 'Continent patch', 0.1566);
  addPatch(335, 72, 55, 38, 0xd9b26a, 'Desert patch', 0.1569);
  addPatch(145, 80, 25, 35, 0x4f8a5a, 'Continent patch 2', 0.1572);

  const capMat = new THREE.MeshStandardMaterial({ color: 0xf2f5f7, roughness: 0.5, metalness: 0.0 });
  const capTop = new THREE.Mesh(new THREE.SphereGeometry(0.1565, 32, 10, phiStart, phiLength, 0, 0.5), capMat);
  capTop.name = 'North ice cap';
  earth.add(capTop);
  const capBottom = new THREE.Mesh(new THREE.SphereGeometry(0.1565, 32, 10, phiStart, phiLength, Math.PI - 0.5, 0.5), capMat);
  capBottom.name = 'South ice cap';
  earth.add(capBottom);

  const markerGeo = new THREE.SphereGeometry(0.008, 18, 12);
  layers.forEach((layer) => {
    const marker = new THREE.Mesh(markerGeo, layer.material);
    marker.position.copy(layer.markerLocal);
    marker.name = layer.name + ' marker';
    earth.add(marker);
    layer.marker = marker;
  });

  const standMat = new THREE.MeshStandardMaterial({ color: 0x3a4048, metalness: 0.6, roughness: 0.4 });
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.105, 0.015, 32), standMat);
  base.position.set(-0.13, 0.0075, -0.04);
  base.name = 'Stand base';
  root.add(base);
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.01, 0.01, 0.05, 16), standMat);
  pole.position.set(-0.13, 0.0325, -0.04);
  pole.name = 'Stand pole';
  root.add(pole);

  const labelYs = [0.33, 0.255, 0.18, 0.105];
  const lineGeo = new THREE.CylinderGeometry(0.0015, 0.0015, 1, 8);
  const dotGeo = new THREE.SphereGeometry(0.0035, 10, 8);
  layers.forEach((layer, i) => {
    const mat = new THREE.MeshBasicMaterial({ color: layer.color });
    const leaderA = new THREE.Mesh(lineGeo, mat);
    leaderA.name = layer.name + ' leader line A';
    root.add(leaderA);
    const leaderB = new THREE.Mesh(lineGeo, mat);
    leaderB.name = layer.name + ' leader line B';
    root.add(leaderB);
    const elbowDot = new THREE.Mesh(dotGeo, mat);
    elbowDot.name = layer.name + ' leader dot';
    root.add(elbowDot);
    layer.leaderA = leaderA;
    layer.leaderB = leaderB;
    layer.elbowDot = elbowDot;
    layer.anchor = new THREE.Vector3(0.082, labelYs[i], 0.10);
    layer.elbowLocal = new THREE.Vector3(0.06, layer.markerLocal.y, 0.16);
  });

  const _up = new THREE.Vector3(0, 1, 0);
  const _target = new THREE.Vector3();
  const _elbow = new THREE.Vector3();
  const _mid = new THREE.Vector3();
  const _dir = new THREE.Vector3();

  function setLine(mesh, from, to) {
    _mid.addVectors(from, to).multiplyScalar(0.5);
    _dir.subVectors(to, from);
    const len = _dir.length();
    mesh.position.copy(_mid);
    if (len < 0.00001) {
      mesh.scale.set(1, 0.00001, 1);
      return;
    }
    _dir.normalize();
    mesh.scale.set(1, len, 1);
    mesh.quaternion.setFromUnitVectors(_up, _dir);
  }

  function updateLines() {
    layers.forEach((layer) => {
      layer.marker.getWorldPosition(_target);
      _elbow.copy(layer.elbowLocal).add(earth.position);
      layer.elbowDot.position.copy(_elbow);
      setLine(layer.leaderA, layer.anchor, _elbow);
      setLine(layer.leaderB, _elbow, _target);
    });
  }

  const defaultFact = 'Tap Show on a label, or press the globe, to explore each layer.';
  let titlePanel = null;
  let selected = -1;

  function select(i) {
    selected = i;
    layers.forEach((layer, idx) => {
      layer.material.emissiveIntensity = idx === i ? 0.9 : 0.12;
    });
    if (titlePanel) {
      titlePanel.set('fact', { text: i < 0 ? defaultFact : layers[i].fact });
    }
  }

  titlePanel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 6px; padding-top: 12px; padding-bottom: 12px;
              padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1a1d22;
              border-width: 2px; border-color: #343a44; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .fact { color: #d7dbe2; font-size: 22px; }
      .note { color: #aeb6c2; font-size: 20px; }
      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px;
              border-radius: 12px; background-color: #3a3f47; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Layers of the Earth</span>
      <span class="fact" id="fact">Tap Show on a label, or press the globe, to explore each layer.</span>
      <span class="note">Not to scale - the crust is drawn thicker so you can see it.</span>
      <div class="row">
        <button class="btn" id="all"><span class="btn-text">Show all</span></button>
        <button class="btn2" id="reset"><span class="btn-text">Reset view</span></button>
      </div>
    </div>`, { width: 0.32, position: [-0.04, 0.435, 0.10], rotationY: 0 });
  root.add(titlePanel.object3D);

  titlePanel.on('all', 'click', () => select(-1));
  titlePanel.on('reset', 'click', () => {
    if (!isGrabbed(earth)) {
      earth.position.copy(center);
      earth.rotation.set(0, 0, 0);
    }
  });

  layers.forEach((layer, i) => {
    const markup = `
    <style>
      .label { width: 420px; flex-direction: column; gap: 6px; padding-top: 11px; padding-bottom: 11px;
               padding-left: 15px; padding-right: 15px; border-radius: 16px; background-color: #1f2228;
               border-width: 2px; border-color: #3a3f47; }
      .row { flex-direction: row; align-items: center; justify-content: space-between; }
      .left { flex-direction: row; align-items: center; gap: 10px; }
      .dot { width: 18px; height: 18px; border-radius: 9px; background-color: ${layer.cssColor}; }
      .name { color: #ffffff; font-size: 24px; font-weight: 700; }
      .detail { color: #d7dbe2; font-size: 20px; }
      .btn { padding-top: 6px; padding-bottom: 6px; padding-left: 12px; padding-right: 12px;
             border-radius: 10px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="label">
      <div class="row">
        <div class="left"><div class="dot"></div><span class="name">${layer.name}</span></div>
        <button class="btn" id="show-${layer.id}"><span class="btn-text">Show</span></button>
      </div>
      <span class="detail">${layer.detail}</span>
    </div>`;
    const panel = ui(markup, { width: 0.26, position: [0.21, labelYs[i], 0.12], rotationY: -0.18 });
    root.add(panel.object3D);
    panel.on('show-' + layer.id, 'click', () => select(i));
  });

  select(-1);

  traits(earth, {
    grab: true,
    onPress: () => {
      const next = (selected + 1) % layers.length;
      select(next);
    }
  });

  updateLines();

  return {
    root,
    update(time) {
      updateLines();
      if (isGrabbed(earth)) return;
      layers.forEach((layer, i) => {
        if (i === selected) {
          layer.marker.scale.setScalar(1.25 + 0.15 * Math.sin(time * 4));
        } else {
          layer.marker.scale.setScalar(1);
        }
      });
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const centre = new THREE.Vector3(-0.09, 0.23, 0);
  const UP = new THREE.Vector3(0, 1, 0);
  const _dir = new THREE.Vector3();

  let info = null;
  let selectedIndex = -1;
  let exploded = false;
  let explodeTarget = 0;
  let explodeValue = 0;

  const overviewText = 'Press a layer in the cut-away, or press its label on the left. The wedge is cut out at the front-left so you can see inside the Earth.';

  const layerDefs = [
    {
      id: 'crust', name: 'Crust', surface: 0x3b82c4, face: 0xa07d50,
      rIn: 0.108, rOut: 0.12, explodeOffset: 0.10, labelY: 0.37,
      target: [-0.193, 0.278, 0.004], textColor: '#8fc3f2',
      fact: 'Crust - 5 to 70 km thick. The thin, solid rock at the surface: continents and ocean floor. We live on it. It is only about 0.5 percent of the radius of Earth, so it is drawn much thicker here.'
    },
    {
      id: 'mantle', name: 'Mantle', surface: 0xc7512f, face: 0xe0662f,
      rIn: 0.068, rOut: 0.108, explodeOffset: 0.06, labelY: 0.285,
      target: [-0.178, 0.23, 0.004], textColor: '#ffab8a',
      fact: 'Mantle - from about 70 km to 2,900 km deep. The thickest layer, about 84 percent of the volume of Earth. Hot solid rock that flows very slowly and moves the tectonic plates.'
    },
    {
      id: 'outer', name: 'Outer Core', surface: 0xff8f1f, face: 0xffa726,
      rIn: 0.036, rOut: 0.068, explodeOffset: 0.025, labelY: 0.20,
      target: [-0.14, 0.217, 0.004], textColor: '#ffcf7a',
      fact: 'Outer Core - from about 2,900 km to 5,150 km deep. Liquid iron and nickel. As this metal moves, it creates the magnetic field of Earth, which shields the surface from harmful space radiation.'
    },
    {
      id: 'inner', name: 'Inner Core', surface: 0xffd94d, face: 0xffe082,
      rIn: 0, rOut: 0.036, explodeOffset: 0, labelY: 0.115,
      target: [-0.108, 0.23, 0.004], textColor: '#ffe98a',
      fact: 'Inner Core - the centre, about 1,220 km in radius. Solid iron and nickel at about 5,500 C, as hot as the surface of the Sun. Huge pressure keeps it solid.'
    }
  ];

  const layers = [];
  const patches = [];

  function selectLayer(index) {
    selectedIndex = index;
    for (let i = 0; i < layers.length; i++) {
      for (let j = 0; j < layers[i].materials.length; j++) {
        layers[i].materials[j].emissiveIntensity = 0;
      }
    }
    if (!info) return;
    if (index < 0) {
      info.set('layerName', { text: 'Overview', color: '#ffffff' });
      info.set('fact', { text: overviewText });
    } else {
      const layer = layers[index];
      for (let j = 0; j < layer.materials.length; j++) {
        layer.materials[j].emissiveIntensity = 0.3;
      }
      info.set('layerName', { text: layer.name, color: layer.textColor });
      info.set('fact', { text: layer.fact });
    }
  }

  layerDefs.forEach((def, index) => {
    const sphereMat = new THREE.MeshStandardMaterial({
      color: def.surface, roughness: 0.5, metalness: 0.05,
      side: THREE.DoubleSide, emissive: def.surface, emissiveIntensity: 0
    });
    const faceMat = new THREE.MeshStandardMaterial({
      color: def.face, roughness: 0.7, metalness: 0.05,
      side: THREE.DoubleSide, emissive: def.face, emissiveIntensity: 0
    });

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(def.rOut, 36, 18, Math.PI / 2, Math.PI * 1.5),
      sphereMat
    );
    sphere.name = def.name;
    sphere.position.copy(centre);
    root.add(sphere);

    let westFace;
    let southFace;
    if (def.rIn > 0) {
      westFace = new THREE.Mesh(new THREE.RingGeometry(def.rIn, def.rOut, 36, 1, Math.PI / 2, Math.PI), faceMat);
      southFace = new THREE.Mesh(new THREE.RingGeometry(def.rIn, def.rOut, 36, 1, -Math.PI / 2, Math.PI), faceMat);
    } else {
      westFace = new THREE.Mesh(new THREE.CircleGeometry(def.rOut, 36, Math.PI / 2, Math.PI), faceMat);
      southFace = new THREE.Mesh(new THREE.CircleGeometry(def.rOut, 36, -Math.PI / 2, Math.PI), faceMat);
    }
    westFace.name = def.name + ' cut face';
    southFace.name = def.name + ' side face';
    westFace.position.copy(centre);
    southFace.position.copy(centre);
    southFace.rotation.y = -Math.PI / 2;
    root.add(westFace);
    root.add(southFace);

    traits(sphere, { onPress: () => selectLayer(index) });
    traits(westFace, { onPress: () => selectLayer(index) });
    traits(southFace, { onPress: () => selectLayer(index) });

    layers.push({
      name: def.name, textColor: def.textColor, explodeOffset: def.explodeOffset,
      meshes: [sphere, westFace, southFace], materials: [sphereMat, faceMat],
      offset: new THREE.Vector3(def.target[0] - centre.x, def.target[1] - centre.y, def.target[2] - centre.z),
      start: new THREE.Vector3(-0.24, def.labelY, 0.03),
      dot: null, leader: null
    });
  });

  const patchDefs = [
    { dir: [0.55, 0.45, 0.70], r: 0.034, color: 0x4f9d4f },
    { dir: [0.78, -0.32, 0.55], r: 0.030, color: 0xc2a35c },
    { dir: [-0.30, 0.55, -0.78], r: 0.032, color: 0x4f9d4f },
    { dir: [0.10, -0.25, -0.96], r: 0.027, color: 0xc2a35c }
  ];
  patchDefs.forEach((p) => {
    const dir = new THREE.Vector3(p.dir[0], p.dir[1], p.dir[2]).normalize();
    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(p.r, 20, 12),
      new THREE.MeshStandardMaterial({ color: p.color, roughness: 0.8 })
    );
    mesh.name = 'Continent';
    mesh.position.copy(centre).addScaledVector(dir, 0.118);
    mesh.scale.set(1, 0.8, 0.22);
    mesh.lookAt(centre.x + dir.x * 2, centre.y + dir.y * 2, centre.z + dir.z * 2);
    root.add(mesh);
    patches.push({ mesh, dir });
  });

  const base = new THREE.Mesh(
    new THREE.CylinderGeometry(0.075, 0.085, 0.016, 32),
    new THREE.MeshStandardMaterial({ color: 0x23272e, roughness: 0.85, metalness: 0.1 })
  );
  base.name = 'Stand base';
  base.position.set(centre.x, 0.008, 0);
  root.add(base);

  const goldRing = new THREE.Mesh(
    new THREE.TorusGeometry(0.075, 0.004, 10, 48),
    new THREE.MeshStandardMaterial({ color: 0xc9a86a, roughness: 0.35, metalness: 0.55 })
  );
  goldRing.name = 'Stand ring';
  goldRing.rotation.x = Math.PI / 2;
  goldRing.position.set(centre.x, 0.016, 0);
  root.add(goldRing);

  const pole = new THREE.Mesh(
    new THREE.CylinderGeometry(0.009, 0.009, 0.22, 16),
    new THREE.MeshStandardMaterial({ color: 0x8b95a3, roughness: 0.4, metalness: 0.6 })
  );
  pole.name = 'Stand pole';
  pole.position.set(centre.x, 0.115, 0);
  root.add(pole);

  const leaderGeo = new THREE.CylinderGeometry(0.0022, 0.0022, 1, 8);
  const dotGeo = new THREE.SphereGeometry(0.006, 16, 10);

  layerDefs.forEach((def, index) => {
    const layer = layers[index];
    const leaderMat = new THREE.MeshStandardMaterial({
      color: def.face, roughness: 0.5, emissive: def.face, emissiveIntensity: 0.15
    });
    const dot = new THREE.Mesh(dotGeo, leaderMat);
    dot.name = def.name + ' pointer';
    dot.position.set(def.target[0], def.target[1], def.target[2]);
    root.add(dot);
    layer.dot = dot;

    const leader = new THREE.Mesh(leaderGeo, leaderMat);
    leader.name = def.name + ' leader line';
    root.add(leader);
    layer.leader = leader;

    const label = ui(`
      <style>
        .label { width: 190px; flex-direction: row; align-items: center; gap: 12px;
                 padding-top: 12px; padding-bottom: 12px; padding-left: 14px; padding-right: 14px;
                 border-radius: 14px; background-color: #1a1d22; border-width: 3px; border-color: #ffffff; }
        .text { color: #ffffff; font-size: 23px; font-weight: 700; }
        .dot { width: 20px; height: 20px; border-radius: 10px; background-color: #ffffff; }
        .b-crust { border-color: #a07d50; } .d-crust { background-color: #a07d50; }
        .b-mantle { border-color: #e0662f; } .d-mantle { background-color: #e0662f; }
        .b-outer { border-color: #ffa726; } .d-outer { background-color: #ffa726; }
        .b-inner { border-color: #ffe082; } .d-inner { background-color: #ffe082; }
      </style>
      <div class="label b-${def.id}" id="sel"><div class="dot d-${def.id}"></div><span class="text">${def.name}</span></div>
    `, { width: 0.16, position: [-0.32, def.labelY, 0.03], rotationY: 0 });
    root.add(label.object3D);
    label.on('sel', 'click', () => selectLayer(index));
  });

  info = ui(`
    <style>
      .card { width: 460px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .subtitle { color: #ffffff; font-size: 24px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .note { color: #aeb6c2; font-size: 19px; }
      .row { flex-direction: row; gap: 10px; justify-content: center; }
      .btn { background-color: #2f6fdb; padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; border-width: 1px; border-color: #2f6fdb; }
      .btn-alt { background-color: #343a44; border-color: #343a44; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Layers of the Earth</span>
      <span class="subtitle" id="layerName">Overview</span>
      <span class="body" id="fact">Press a layer in the cut-away, or press its label on the left. The wedge is cut out at the front-left so you can see inside the Earth.</span>
      <span class="note">Note: Layer thicknesses are exaggerated. Real crust is only about 0.5 percent of the radius of Earth.</span>
      <div class="row">
        <button class="btn" id="explodeBtn"><span class="btn-text" id="explodeText">Explode layers</span></button>
        <button class="btn" id="nextBtn"><span class="btn-text">Next layer</span></button>
        <button class="btn btn-alt" id="overviewBtn"><span class="btn-text">Overview</span></button>
      </div>
    </div>`, { width: 0.34, position: [0.23, 0.24, 0.02], rotationY: -0.25 });
  root.add(info.object3D);

  info.on('explodeBtn', 'click', () => {
    exploded = !exploded;
    explodeTarget = exploded ? 1 : 0;
    info.set('explodeText', { text: exploded ? 'Assemble layers' : 'Explode layers' });
  });
  info.on('nextBtn', 'click', () => selectLayer((selectedIndex + 1) % layers.length));
  info.on('overviewBtn', 'click', () => selectLayer(-1));

  selectLayer(-1);

  return {
    root,
    update(time, delta) {
      const dt = delta || 0.016;
      explodeValue += (explodeTarget - explodeValue) * Math.min(1, dt * 2.2);
      if (Math.abs(explodeTarget - explodeValue) < 0.001) explodeValue = explodeTarget;

      for (let i = 0; i < layers.length; i++) {
        const layer = layers[i];
        const s = 1 + explodeValue * layer.explodeOffset;
        for (let j = 0; j < layer.meshes.length; j++) {
          layer.meshes[j].scale.setScalar(s);
        }
        layer.dot.position.copy(centre).addScaledVector(layer.offset, s);
        _dir.copy(layer.dot.position).sub(layer.start);
        const len = _dir.length();
        layer.leader.position.copy(layer.start).lerp(layer.dot.position, 0.5);
        if (len > 0.0001) {
          _dir.normalize();
          layer.leader.quaternion.setFromUnitVectors(UP, _dir);
          layer.leader.scale.set(1, len, 1);
        }
      }

      const crustScale = 1 + explodeValue * layers[0].explodeOffset;
      for (let i = 0; i < patches.length; i++) {
        const patch = patches[i];
        patch.mesh.position.copy(centre).addScaledVector(patch.dir, 0.12 * crustScale - 0.002);
        patch.mesh.scale.set(crustScale, crustScale * 0.8, crustScale * 0.22);
      }

      if (selectedIndex >= 0) {
        const pulse = 0.26 + 0.12 * Math.sin(time * 3.0);
        layers[selectedIndex].materials[0].emissiveIntensity = pulse;
        layers[selectedIndex].materials[1].emissiveIntensity = pulse;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'WeatherDashboard';

  const cities = [
    { name: 'Phoenix', tempC: 34, condition: 'Sunny', humidity: 18, wind: 12 },
