  const cloudGeo = new THREE.SphereGeometry(0.027, 20, 14);
  function makeCloud(material, name) {
    const group = new THREE.Group();
    group.name = name;
    const puffs = [
      [0, 0, 0, 1.0],
      [-0.026, -0.004, 0, 0.78],
