      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">WEATHER DASHBOARD</span>
      <div class="row">
        <div class="city"><span class="city-name">PHOENIX</span><span class="temp temp0" id="temp0">34 C</span><span class="cond">Sunny</span></div>
        <div class="city"><span class="city-name">LONDON</span><span class="temp temp1" id="temp1">14 C</span><span class="cond">Rain</span></div>
        <div class="city"><span class="city-name">CHICAGO</span><span class="temp temp2" id="temp2">-2 C</span><span class="cond">Snow</span></div>
