      for (let i = 0; i < snowFlakes.length; i++) {
        const f = snowFlakes[i];
        const cycle = (time * 0.04 + f.phase) % 0.06;
        f.mesh.position.y = -0.026 - cycle;
        f.mesh.position.x = f.baseX + Math.sin(time * 2.0 + f.phase * 4.0) * 0.004;
      }
      for (let i = 0; i < icons.length; i++) {
        if (isGrabbed(icons[i])) continue;
        const target = i === selected ? 1.14 : 1.0;
        iconScales[i] += (target - iconScales[i]) * Math.min(1, step * 10);
        icons[i].scale.setScalar(iconScales[i]);
      }
    },
  };
}

