  });

  return {
    root,
    update(time) {
      if (!steamGroup.visible || isGrabbed(mug)) return;
      for (let i = 0; i < puffs.length; i++) {
        const p = puffs[i];
        const t = (time * 0.28 + p.phase) % 1;
        p.mesh.position.y = 0.108 + t * 0.065;
        p.mesh.position.x = p.drift + Math.sin(time * 1.2 + p.phase * 6.283) * 0.004 * t;
        p.mesh.scale.setScalar(0.6 + t * 1.1);
        p.mesh.material.opacity = 0.32 * (1 - t);
      }
    }
  };
}

