  sunIcon.add(makeDisc());
  const sunBall = new THREE.Mesh(
    new THREE.SphereGeometry(0.027, 24, 16),
    new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff8a00, emissiveIntensity: 0.85, roughness: 0.5 })
  );
  sunBall.name = 'Sun';
  sunIcon.add(sunBall);
  const sunRays = new THREE.Group();
  sunRays.name = 'Sun rays';
  sunIcon.add(sunRays);
  const rayGeo = new THREE.BoxGeometry(0.008, 0.022, 0.008);
  const rayMat = new THREE.MeshStandardMaterial({ color: 0xffd166, emissive: 0xff9f1a, emissiveIntensity: 0.6 });
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const ray = new THREE.Mesh(rayGeo, rayMat);
    ray.position.set(Math.cos(a) * 0.042, Math.sin(a) * 0.042, 0);
    ray.rotation.z = a - Math.PI / 2;
    sunRays.add(ray);
  }

  const rainIcon = new THREE.Group();
  rainIcon.name = 'London Rain icon';
  rainIcon.position.set(xs[1], 0.40, -0.04);
  rainIcon.userData.baseY = 0.40;
  root.add(rainIcon);
  rainIcon.add(makeDisc());
  const rainCloud = makeCloud(new THREE.MeshStandardMaterial({ color: 0x9aa5b1, roughness: 0.95 }));
  rainCloud.name = 'Rain cloud';
  rainIcon.add(rainCloud);
  const rainDrops = [];
  const dropGeo = new THREE.SphereGeometry(0.007, 12, 10);
  const dropMat = new THREE.MeshStandardMaterial({ color: 0x3b82f6, emissive: 0x1d4ed8, emissiveIntensity: 0.5 });
  for (let i = 0; i < 3; i++) {
    const drop = new THREE.Mesh(dropGeo, dropMat);
    drop.name = 'Rain drop';
    drop.scale.set(1, 1.7, 1);
    const bx = -0.02 + i * 0.02;
    drop.position.set(bx, -0.03, 0);
    drop.userData.baseX = bx;
    drop.userData.baseY = -0.03;
    rainIcon.add(drop);
    rainDrops.push(drop);
  }

  const snowIcon = new THREE.Group();
  snowIcon.name = 'Reykjavik Snow icon';
  snowIcon.position.set(xs[2], 0.40, -0.04);
  snowIcon.userData.baseY = 0.40;
  root.add(snowIcon);
  snowIcon.add(makeDisc());
  const snowCloud = makeCloud(new THREE.MeshStandardMaterial({ color: 0xe8eef5, roughness: 0.9 }));
  snowCloud.name = 'Snow cloud';
  snowIcon.add(snowCloud);
  const snowFlakes = [];
  const flakeGeo = new THREE.SphereGeometry(0.006, 12, 10);
  const flakeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0x9fd8ef, emissiveIntensity: 0.6 });
  const flakeXs = [-0.024, -0.008, 0.01, 0.026];
  for (let i = 0; i < 4; i++) {
    const flake = new THREE.Mesh(flakeGeo, flakeMat);
    flake.name = 'Snow flake';
    const by = -0.028 - (i % 2) * 0.006;
    flake.position.set(flakeXs[i], by, 0);
    flake.userData.baseX = flakeXs[i];
    flake.userData.baseY = by;
    snowIcon.add(flake);
    snowFlakes.push(flake);
  }

  const icons = [sunIcon, rainIcon, snowIcon];
  let useCelsius = true;

  function selectCity(index) {
    const city = cities[index];
    detailPanel.set('detailTitle', { text: city.name + ', ' + city.country + ' - ' + city.condition });
    detailPanel.set('detailBody', { text: 'Humidity ' + city.humidity + '% - Wind ' + city.wind + ' km/h. ' + city.forecast });
    for (let j = 0; j < 3; j++) {
      icons[j].scale.setScalar(j === index ? 1.18 : 1.0);
    }
  }

  function updateTemps() {
    for (let i = 0; i < 3; i++) {
      cardPanels[i].set('temp', { text: useCelsius ? cities[i].tempC : cities[i].tempF });
    }
  }

  detailPanel.on('units', 'click', () => {
    useCelsius = !useCelsius;
    updateTemps();
    detailPanel.set('unitsLabel', { text: useCelsius ? 'Show Fahrenheit' : 'Show Celsius' });
  });

  traits(sunIcon, { onPress: () => selectCity(0) });
  traits(rainIcon, { onPress: () => selectCity(1) });
  traits(snowIcon, { onPress: () => selectCity(2) });

  return {
    root,
    update(time, delta) {
      if (!isGrabbed(sunIcon)) sunRays.rotation.z = time * 0.35;
      for (let i = 0; i < icons.length; i++) {
        const icon = icons[i];
        if (!isGrabbed(icon)) {
          icon.position.y = icon.userData.baseY + Math.sin(time * 1.3 + i * 1.7) * 0.004;
        }
      }
      for (let i = 0; i < rainDrops.length; i++) {
        const drop = rainDrops[i];
        drop.position.y = drop.userData.baseY + Math.sin(time * 2.2 + i * 2.1) * 0.005;
        drop.position.x = drop.userData.baseX + Math.sin(time * 1.5 + i) * 0.002;
      }
      for (let i = 0; i < snowFlakes.length; i++) {
        const flake = snowFlakes[i];
        flake.position.y = flake.userData.baseY + Math.sin(time * 1.1 + i * 1.9) * 0.007;
        flake.position.x = flake.userData.baseX + Math.sin(time * 0.8 + i) * 0.003;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'MultiplicationQuiz';

  const questions = [
    { a: 3, b: 4, options: [10, 12, 9, 15], answer: 12 },
    { a: 6, b: 7, options: [42, 36, 48, 40], answer: 42 },
    { a: 8, b: 5, options: [35, 32, 45, 40], answer: 40 },
    { a: 9, b: 6, options: [46, 54, 63, 48], answer: 54 },
    { a: 7, b: 7, options: [42, 49, 56, 38], answer: 49 }
  ];

  let current = 0;
  let score = 0;
  let answered = 0;
  let locked = false;
  let finished = false;
  let currentA = 3;
  let currentB = 4;

  const board = new THREE.Group();
  board.name = 'DotBoard';
  board.position.set(0, 0, 0.08);
  root.add(board);

  const base = new THREE.Mesh(
    new THREE.BoxGeometry(0.30, 0.008, 0.26),
    new THREE.MeshStandardMaterial({ color: 0xe8890c, roughness: 0.6 })
  );
  base.name = 'BoardBase';
  base.position.y = 0.004;
  board.add(base);

  const plate = new THREE.Mesh(
    new THREE.BoxGeometry(0.28, 0.01, 0.24),
    new THREE.MeshStandardMaterial({ color: 0x1f2a38, roughness: 0.75 })
  );
  plate.name = 'BoardPlate';
  plate.position.y = 0.013;
  board.add(plate);

  const dotGeometry = new THREE.SphereGeometry(0.0075, 12, 8);
  const dotMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.35 });
  const dots = new THREE.InstancedMesh(dotGeometry, dotMaterial, 81);
  dots.name = 'MultiplicationDots';
  dots.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  dots.frustumCulled = false;
  dots.count = 0;
  board.add(dots);

  const dummy = new THREE.Object3D();
  const palette = [0xff6b6b, 0xffa94d, 0xffd43b, 0x69db7c, 0x4dabf7, 0xb197fc, 0xf783ac, 0x63e6be, 0xffa8a8].map((hex) => new THREE.Color(hex));

  function rebuildDots(a, b) {
    currentA = a;
    currentB = b;
    dots.count = a * b;
    let idx = 0;
    for (let row = 0; row < a; row++) {
      for (let col = 0; col < b; col++) {
        dummy.position.set((col - (b - 1) / 2) * 0.021, 0.0255, (row - (a - 1) / 2) * 0.021);
        dummy.scale.set(1, 1, 1);
        dummy.rotation.set(0, 0, 0);
        dummy.updateMatrix();
        dots.setMatrixAt(idx, dummy.matrix);
        dots.setColorAt(idx, palette[row % palette.length]);
        idx++;
      }
    }
    dots.instanceMatrix.needsUpdate = true;
    if (dots.instanceColor) dots.instanceColor.needsUpdate = true;
  }

  function layoutPulse(time) {
    if (dots.count === 0) return;
    let idx = 0;
    for (let row = 0; row < currentA; row++) {
      const scale = 1 + 0.06 * Math.sin(time * 2.2 + row * 0.7);
      for (let col = 0; col < currentB; col++) {
        dummy.position.set((col - (currentB - 1) / 2) * 0.021, 0.0255, (row - (currentA - 1) / 2) * 0.021);
        dummy.scale.set(scale, scale, scale);
        dummy.rotation.set(0, 0, 0);
        dummy.updateMatrix();
        dots.setMatrixAt(idx, dummy.matrix);
        idx++;
      }
    }
    dots.instanceMatrix.needsUpdate = true;
  }

  const info = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1a1d22; border-width: 2px; border-color: #3a3f47; }
      .topRow { display: flex; flex-direction: row; justify-content: space-between; align-items: center; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .badge { color: #ffd54d; font-size: 22px; font-weight: 700; background-color: #2a2e35; padding-top: 6px; padding-bottom: 6px; padding-left: 12px; padding-right: 12px; border-radius: 12px; }
      .scoreRow { display: flex; flex-direction: row; justify-content: space-between; align-items: center; }
      .scoreLabel { color: #d7dbe2; font-size: 22px; font-weight: 700; }
      .question { color: #ffffff; font-size: 36px; font-weight: 700; text-align: center; }
      .feedback { color: #d7dbe2; font-size: 22px; text-align: center; }
      .hint { color: #9fb0c3; font-size: 22px; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 12px; }
      .btn { width: 224px; height: 52px; display: flex; align-items: center; justify-content: center; border-radius: 12px; background-color: #2f6fdb; }
      .nextBtn { width: 460px; height: 52px; display: none; align-items: center; justify-content: center; border-radius: 12px; background-color: #2e9e62; }
      .restartBtn { width: 460px; height: 52px; display: none; align-items: center; justify-content: center; border-radius: 12px; background-color: #e8890c; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="topRow">
        <span class="title">Multiplication Quiz</span>
        <span class="badge" id="progress">Question 1 of 5</span>
      </div>
      <div class="scoreRow">
        <span class="scoreLabel" id="score">Score: 0</span>
        <span class="scoreLabel" id="answered">Answered: 0 of 5</span>
      </div>
      <span class="question" id="question">3 x 4 = ?</span>
      <span class="feedback" id="feedback">Pick the correct answer.</span>
      <span class="hint" id="arrayDesc">Dots below: 3 rows of 4. Count them.</span>
      <div class="row">
        <button class="btn" id="opt0"><span class="btn-text" id="opt0t">10</span></button>
        <button class="btn" id="opt1"><span class="btn-text" id="opt1t">12</span></button>
      </div>
      <div class="row">
        <button class="btn" id="opt2"><span class="btn-text" id="opt2t">9</span></button>
        <button class="btn" id="opt3"><span class="btn-text" id="opt3t">15</span></button>
      </div>
      <button class="nextBtn" id="next"><span class="btn-text" id="nextText">Next question</span></button>
      <button class="restartBtn" id="restart"><span class="btn-text">Play again</span></button>
    </div>`, { width: 0.42, position: [0, 0.31, 0], rotationY: 0 });
  root.add(info.object3D);

  function showQuestion() {
    const q = questions[current];
    locked = false;
    finished = false;
    info.set('progress', { text: 'Question ' + (current + 1) + ' of 5' });
    info.set('score', { text: 'Score: ' + score });
    info.set('answered', { text: 'Answered: ' + answered + ' of 5' });
    info.set('question', { text: q.a + ' x ' + q.b + ' = ?' });
    info.set('feedback', { text: 'Pick the correct answer.', color: '#d7dbe2' });
    info.set('arrayDesc', { text: 'Dots below: ' + q.a + ' rows of ' + q.b + '. Count them.' });
    for (let i = 0; i < 4; i++) {
      info.set('opt' + i + 't', { text: String(q.options[i]) });
      info.set('opt' + i, { display: 'flex', backgroundColor: '#2f6fdb' });
    }
    info.set('nextText', { text: 'Next question' });
    info.set('next', { display: 'none' });
    info.set('restart', { display: 'none' });
    rebuildDots(q.a, q.b);
  }

  function showResults() {
    finished = true;
    let message = 'Good try! Play again to improve.';
    let messageColor = '#ffd54d';
    if (score === 5) {
      message = 'Excellent! Perfect score.';
      messageColor = '#7ee2a0';
    } else if (score >= 3) {
      message = 'Great work! Keep practicing.';
      messageColor = '#7ee2a0';
    }
    info.set('progress', { text: 'Quiz complete' });
    info.set('question', { text: 'You scored ' + score + ' out of 5' });
    info.set('feedback', { text: message, color: messageColor });
    info.set('arrayDesc', { text: 'Press Play again for another round.' });
    for (let i = 0; i < 4; i++) {
      info.set('opt' + i, { display: 'none' });
    }
    info.set('next', { display: 'none' });
    info.set('restart', { display: 'flex' });
    dots.count = 0;
    dots.instanceMatrix.needsUpdate = true;
  }

  function handleAnswer(index) {
    if (locked || finished) return;
    locked = true;
    answered++;
    const q = questions[current];
    const chosen = q.options[index];
    const correctIndex = q.options.indexOf(q.answer);
    if (chosen === q.answer) {
      score++;
      info.set('feedback', { text: 'Correct! ' + q.a + ' x ' + q.b + ' = ' + q.answer + '.', color: '#7ee2a0' });
      info.set('opt' + index, { backgroundColor: '#2e9e62' });
    } else {
      info.set('feedback', { text: 'Not quite. ' + q.a + ' x ' + q.b + ' = ' + q.answer + '.', color: '#ff9a9a' });
      info.set('opt' + index, { backgroundColor: '#b33a3a' });
      info.set('opt' + correctIndex, { backgroundColor: '#2e9e62' });
    }
    info.set('score', { text: 'Score: ' + score });
    info.set('answered', { text: 'Answered: ' + answered + ' of 5' });
    info.set('nextText', { text: current === 4 ? 'See results' : 'Next question' });
    info.set('next', { display: 'flex' });
  }

  function handleNext() {
    if (!locked || finished) return;
    if (current < 4) {
      current++;
      showQuestion();
    } else {
      showResults();
    }
  }

  function handleRestart() {
    if (!finished) return;
    current = 0;
    score = 0;
    answered = 0;
    showQuestion();
  }

  info.on('opt0', 'click', () => handleAnswer(0));
  info.on('opt1', 'click', () => handleAnswer(1));
  info.on('opt2', 'click', () => handleAnswer(2));
  info.on('opt3', 'click', () => handleAnswer(3));
  info.on('next', 'click', handleNext);
  info.on('restart', 'click', handleRestart);

  showQuestion();
  traits(board, { grab: true });

  return {
    root,
    update(time) {
      if (isGrabbed(board)) return;
      layoutPulse(time);
    }
  };
}

