  const railFront = new THREE.Mesh(railLongGeo, railMat);
  railFront.position.set(0, 0.004, 0.088);
  tray.add(railFront);

  const railBack = new THREE.Mesh(railLongGeo, railMat);
  railBack.position.set(0, 0.004, -0.088);
  tray.add(railBack);

  const railLeft = new THREE.Mesh(railShortGeo, railMat);
  railLeft.position.set(-0.182, 0.004, 0);
  tray.add(railLeft);

  const railRight = new THREE.Mesh(railShortGeo, railMat);
  railRight.position.set(0.182, 0.004, 0);
  tray.add(railRight);

  const dotGeo = new THREE.SphereGeometry(0.0055, 10, 7);
  const dotMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.35 });
  const dots = new THREE.InstancedMesh(dotGeo, dotMat, 108);
  dots.name = 'MultiplicationDots';
  tray.add(dots);

  const dummy = new THREE.Object3D();
  const colorA = new THREE.Color(0x2ec4b6);
  const colorB = new THREE.Color(0x4a90e2);
  const colorGold = new THREE.Color(0xffc23d);

  function renderDots(q, gold) {
    const rows = q.a;
    const cols = q.b;
    const usableW = 0.32;
    const usableD = 0.15;
    const spacingX = usableW / cols;
    const spacingZ = usableD / rows;
    let idx = 0;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        dummy.position.set(
          -usableW / 2 + spacingX * (c + 0.5),
          0.011,
          -usableD / 2 + spacingZ * (r + 0.5)
        );
        dummy.rotation.set(0, 0, 0);
        dummy.scale.set(1, 1, 1);
        dummy.updateMatrix();
        dots.setMatrixAt(idx, dummy.matrix);
        dots.setColorAt(idx, gold ? colorGold : (r % 2 === 0 ? colorA : colorB));
        idx++;
      }
    }
    dots.count = idx;
    dots.instanceMatrix.needsUpdate = true;
    if (dots.instanceColor) dots.instanceColor.needsUpdate = true;
  }

  const stand = new THREE.Mesh(
    new THREE.BoxGeometry(0.22, 0.07, 0.06),
    new THREE.MeshStandardMaterial({ color: 0x39404d, roughness: 0.7 })
  );
  stand.name = 'ScoreStand';
  stand.position.set(0.24, 0.035, 0.08);
  root.add(stand);

  const gemGeo = new THREE.OctahedronGeometry(0.018, 0);
  const gemGoldMat = new THREE.MeshStandardMaterial({
    color: 0xffc23d,
    emissive: 0xff9f00,
    emissiveIntensity: 0.65,
    metalness: 0.25,
    roughness: 0.25
  });
  const gemGrayMat = new THREE.MeshStandardMaterial({
    color: 0x6b7480,
    roughness: 0.5,
    metalness: 0.1
  });
  const gems = [];
  for (let i = 0; i < 5; i++) {
    const gem = new THREE.Mesh(gemGeo, gemGrayMat);
    gem.name = 'ScoreGem' + (i + 1);
    gem.position.set(0.155 + i * 0.045, 0.088, 0.08);
    root.add(gem);
    gems.push(gem);
    traits(gem, { grab: true });
  }

  function setFeedback(text) {
    currentFeedback = text;
    if (!hintOn) info.set('feedback', { text: text });
  }

  function hintText(q) {
    const parts = [];
    for (let i = 1; i <= q.a; i++) parts.push(String(i * q.b));
    let seq = parts.join(', ');
    if (seq.length > 56) seq = parts.slice(0, 5).join(', ') + ', ... ' + String(q.ans);
    return 'Count by ' + q.b + ': ' + seq;
  }

  function showQuestion() {
    answered = false;
    hintOn = false;
    const q = questions[current];
    info.set('progress', { text: 'Question ' + (current + 1) + ' of 5' });
    info.set('question', { text: q.a + ' x ' + q.b + ' = ?' });
    info.set('score', { text: 'Score: ' + score + ' correct - ' + answeredCount + ' answered' });
    setFeedback('Choose an answer below, then tap Next question.');
    info.set('row1', { display: 'flex' });
    info.set('row2', { display: 'flex' });
    for (let j = 0; j < 4; j++) {
      info.set('a' + j + 't', { text: String(q.options[j]), color: '#ffffff' });
      info.set('a' + j, { backgroundColor: '#2f3b52' });
    }
    info.set('nextt', { text: 'Next question' });
    renderDots(q, false);
  }

  function chooseAnswer(index) {
    if (answered || finished) return;
    answered = true;
    answeredCount++;
    hintOn = false;
    const q = questions[current];
    const correctIndex = q.options.indexOf(q.ans);
    let message;
    if (index === correctIndex) {
      score++;
      gems[score - 1].material = gemGoldMat;
      renderDots(q, true);
      message = 'Correct! ' + q.a + ' x ' + q.b + ' = ' + q.ans + '. Great work.';
    } else {
      message = 'Not quite. ' + q.a + ' x ' + q.b + ' = ' + q.ans + '. Look at the dots: ' + q.a + ' groups of ' + q.b + '.';
    }
    for (let j = 0; j < 4; j++) {
      if (j === correctIndex) {
        info.set('a' + j, { backgroundColor: '#1f8a4c' });
        info.set('a' + j + 't', { color: '#ffffff' });
      } else if (j === index) {
        info.set('a' + j, { backgroundColor: '#b3312c' });
        info.set('a' + j + 't', { color: '#ffffff' });
      } else {
        info.set('a' + j, { backgroundColor: '#23262c' });
        info.set('a' + j + 't', { color: '#8a929e' });
      }
    }
    info.set('score', { text: 'Score: ' + score + ' correct - ' + answeredCount + ' answered' });
    setFeedback(message);
    info.set('nextt', { text: current === questions.length - 1 ? 'See results' : 'Next question' });
  }

  function showResults() {
    finished = true;
    hintOn = false;
    const encouragement = score >= 4
      ? 'Excellent! You know your multiplication facts.'
      : score === 3
        ? 'Good job! Review the ones you missed and try again.'
        : 'Good try! Look at the dot groups and play again to practise.';
    info.set('progress', { text: 'All 5 questions done' });
    info.set('question', { text: 'You scored ' + score + ' of 5' });
    info.set('score', { text: 'Final score: ' + score + ' correct - 5 answered' });
    setFeedback(encouragement);
    info.set('row1', { display: 'none' });
    info.set('row2', { display: 'none' });
    info.set('nextt', { text: 'Play again' });
  }

  function restart() {
    score = 0;
    answeredCount = 0;
    current = 0;
    finished = false;
    for (let i = 0; i < gems.length; i++) {
      gems[i].material = gemGrayMat;
      gems[i].scale.set(1, 1, 1);
    }
    showQuestion();
  }

  for (let i = 0; i < 4; i++) {
    info.on('a' + i, 'click', () => chooseAnswer(i));
  }

  info.on('next', 'click', () => {
    if (finished) {
      restart();
    } else if (!answered) {
      setFeedback('Choose an answer first, then tap Next question.');
    } else if (current < questions.length - 1) {
      current++;
      showQuestion();
    } else {
      showResults();
    }
  });

  traits(tray, {
    grab: true,
    onPress: () => {
      hintOn = !hintOn;
      if (hintOn) {
        info.set('feedback', { text: hintText(questions[current]) });
      } else {
        info.set('feedback', { text: currentFeedback });
      }
    }
  });

  showQuestion();

  return {
    root,
    update(time, delta) {
      for (let i = 0; i < gems.length; i++) {
        const gem = gems[i];
        if (isGrabbed(gem)) continue;
        const isGold = gem.material === gemGoldMat;
        gem.rotation.y += delta * (isGold ? 1.4 : 0.35);
        if (isGold) {
          const s = 1 + Math.sin(time * 3 + i * 0.7) * 0.06;
          gem.scale.set(s, s, s);
        } else {
          gem.scale.set(1, 1, 1);
        }
      }
    }
  };
}

