  root.add(info.object3D);

  function countDone(days) {
    let n = 0;
    for (let i = 0; i < days.length; i++) if (days[i]) n++;
    return n;
  }

  // Streak: consecutive checked days ending at the latest checked day.
  function streakFor(days) {
    let i = days.length - 1;
    while (i >= 0 && !days[i]) i--;
    let s = 0;
    while (i >= 0 && days[i]) { s++; i--; }
    return s;
  }

