  }

  habits.forEach((h, hi) => {
    h.days.forEach((unused, di) => {
      info.on('b' + hi + di, 'click', () => {
        h.days[di] = !h.days[di];
        refresh();
        const s = streakFor(h.days);
        info.set('detail', { text: h.name + ' ' + (h.days[di] ? 'checked' : 'unchecked') + ' - streak ' + s + (s === 1 ? ' day.' : ' days.') });
      });
    });

    traits(h.flame, {
      onPress: () => info.set('detail', { text: h.tip }),
    });
  });

  info.on('resetbtn', 'click', () => {
    habits.forEach((h) => {
      for (let i = 0; i < h.days.length; i++) h.days[i] = false;
    });
    refresh();
    info.set('detail', { text: 'Week cleared. Tap a day to start again.' });
  });

  refresh();

  return {
    root,
    update(time) {
      for (let i = 0; i < habits.length; i++) {
        const f = habits[i].flame;
        const s = 1 + Math.sin(time * 3 + i * 1.7) * 0.07;
        f.scale.x = s;
        f.scale.z = s;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
