    color: 0xffcf4d, emissive: 0xffb300, emissiveIntensity: 0.7, roughness: 0.3,
  });

  for (let i = 0; i < habits.length; i++) {
    const h = habits[i];
    const x = -0.21 + i * 0.21;
    const z = 0.27;

    const base = new THREE.Mesh(baseGeometry, new THREE.MeshStandardMaterial({ color: h.color, roughness: 0.55 }));
    base.name = h.name + ' base';
    base.position.set(x, 0.0135, z);
    root.add(base);

    const cup = new THREE.Mesh(cupGeometry, new THREE.MeshStandardMaterial({
      color: h.color, transparent: true, opacity: 0.28, roughness: 0.2, side: THREE.DoubleSide,
    }));
    cup.name = h.name + ' cup';
    cup.position.set(x, 0.053, z);
    root.add(cup);

    const fill = new THREE.Mesh(fillGeometry, new THREE.MeshStandardMaterial({
      color: h.color, roughness: 0.5, emissive: h.color, emissiveIntensity: 0.25,
    }));
    fill.name = h.name + ' fill';
    fill.position.set(x, 0.018, z);
    root.add(fill);

    const ball = new THREE.Mesh(ballGeometry, new THREE.MeshStandardMaterial({
      color: h.color, roughness: 0.35, emissive: h.color, emissiveIntensity: 0.25,
    }));
    ball.name = h.name + ' ball';
    ball.position.set(x, 0.112, z);
    root.add(ball);

    const star = new THREE.Mesh(starGeometry, starMaterial);
    star.name = h.name + ' star';
    star.position.set(x, 0.155, z);
    root.add(star);

    tokens.push({ ball, fill, star });
