    rowsMarkup += '<div class="row">';
    rowsMarkup += '<span class="habit-name c' + i + '">' + habits[i].name + '</span>';
    for (let d = 0; d < 7; d++) {
      rowsMarkup += '<button class="day" id="b' + i + '_' + d + '"><span class="day-text" id="t' + i + '_' + d + '">-</span></button>';
    }
    rowsMarkup += '<div class="streak-box"><span class="streak" id="streak' + i + '">Streak 0</span><span class="count" id="count' + i + '">0/7 done</span></div>';
    rowsMarkup += '</div>';
  }

  const markup = `
    <style>
      .card { width: 560px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1a1d22; border-width: 2px; border-color: #343a44; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #d7dbe2; font-size: 20px; }
      .sub2 { color: #9fb0c3; font-size: 19px; }
      .row { flex-direction: row; align-items: center; gap: 6px; }
      .habit-head { width: 124px; color: #aeb6c2; font-size: 18px; font-weight: 700; }
      .day-head { width: 36px; color: #aeb6c2; font-size: 18px; font-weight: 700; text-align: center; }
      .today-head { width: 36px; color: #ffb84d; font-size: 18px; font-weight: 700; text-align: center; }
      .streak-head { width: 88px; color: #aeb6c2; font-size: 18px; font-weight: 700; }
      .habit-name { width: 124px; font-size: 20px; font-weight: 700; }
      .c0 { color: #8cc0ff; }
      .c1 { color: #6fe0d4; }
      .c2 { color: #ffc46b; }
      .day { width: 36px; height: 36px; padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px; border-radius: 10px; background-color: #2a2e35; border-width: 1px; border-color: #414854; }
      .day-text { color: #eef1f6; font-size: 20px; font-weight: 700; text-align: center; }
      .streak-box { width: 88px; flex-direction: column; gap: 2px; align-items: flex-start; }
      .streak { color: #ffd166; font-size: 20px; font-weight: 700; }
      .count { color: #c3cad4; font-size: 17px; }
      .footer { flex-direction: row; align-items: center; justify-content: space-between; gap: 10px; }
      .total { color: #ffffff; font-size: 20px; font-weight: 700; }
      .btn-row { flex-direction: row; gap: 8px; align-items: center; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #3a4048; border-width: 1px; border-color: #4a5260; }
      .accent { background-color: #2e9e62; border-color: #3fbd7d; }
      .btn-text { color: #ffffff; font-size: 19px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">This Week - Habit Tracker</span>
      <span class="sub">Tap a day to check it off. Today is Wednesday.</span>
      <span class="sub2">Streak counts back from today. Pinch a ball below to check today.</span>
      <div class="row">${headerMarkup}</div>
      ${rowsMarkup}
      <div class="footer">
        <span class="total" id="total">Total: 0 of 21 done</span>
        <div class="btn-row">
          <button class="btn accent" id="todayAll"><span class="btn-text">Check all today</span></button>
          <button class="btn" id="reset"><span class="btn-text">Reset week</span></button>
        </div>
      </div>
    </div>`;

  const info = ui(markup, { width: 0.5, position: [0, 0.28, 0], rotationY: 0 });
  root.add(info.object3D);

  function streakFor(h) {
    let index = h.days[TODAY] ? TODAY : TODAY - 1;
    let streak = 0;
    while (index >= 0 && h.days[index]) {
      streak++;
      index--;
    }
    return streak;
  }

  function refresh() {
    let grandTotal = 0;
    for (let i = 0; i < habits.length; i++) {
      const h = habits[i];
      let count = 0;
      for (let d = 0; d < 7; d++) {
        const done = h.days[d];
        if (done) count++;
        info.set('t' + i + '_' + d, { text: done ? 'X' : '-' });
        info.set('b' + i + '_' + d, { backgroundColor: done ? h.css : '#2a2e35' });
      }
      info.set('streak' + i, { text: 'Streak ' + streakFor(h) });
      info.set('count' + i, { text: count + '/7 done' });
      grandTotal += count;

      // Update the 3D cup fill for this habit.
      const fillHeight = 0.06 * (count / 7);
      tokens[i].fill.scale.y = Math.max(fillHeight, 0.0001);
      tokens[i].fill.position.y = 0.018 + fillHeight * 0.5;
      tokens[i].star.visible = h.days[TODAY];
      tokens[i].ball.material.emissiveIntensity = h.days[TODAY] ? 0.65 : 0.22;
    }
    let totalText = 'Total: ' + grandTotal + ' of 21 done';
    if (grandTotal === 21) totalText = 'Total: 21 of 21 done - perfect week!';
    info.set('total', { text: totalText });
  }

  function toggleDay(i, d) {
    habits[i].days[d] = !habits[i].days[d];
    refresh();
  }

  for (let i = 0; i < habits.length; i++) {
    for (let d = 0; d < 7; d++) {
      const hi = i;
      const di = d;
      info.on('b' + hi + '_' + di, 'click', () => toggleDay(hi, di));
    }
  }

  info.on('todayAll', 'click', () => {
    for (let i = 0; i < habits.length; i++) habits[i].days[TODAY] = true;
    refresh();
  });

  info.on('reset', 'click', () => {
    for (let i = 0; i < habits.length; i++) habits[i].days = [false, false, false, false, false, false, false];
    refresh();
  });

  for (let i = 0; i < tokens.length; i++) {
    const hi = i;
    traits(tokens[hi].ball, { grab: true, onPress: () => toggleDay(hi, TODAY) });
  }

  refresh();

  return {
    root,
    update(time) {
      for (let i = 0; i < tokens.length; i++) {
        const star = tokens[i].star;
        star.rotation.y = time * 1.6 + i * 1.3;
        star.position.y = 0.155 + Math.sin(time * 2 + i * 1.7) * 0.004;
      }
    },
  };
}

