  ring.position.copy(CENTER);
  root.add(ring);

  // Faint target shape: guide bonds and ghost atoms
  const guideGeo = new THREE.CylinderGeometry(0.003, 0.003, 1, 8);
  const guideMat = new THREE.MeshBasicMaterial({ color: 0x4dc3b8, transparent: true, opacity: 0.22 });
  const up = new THREE.Vector3(0, 1, 0);
  const guideDir = new THREE.Vector3();
  for (let i = 0; i < TARGETS.length; i++) {
    guideDir.subVectors(TARGETS[i], CENTER);
    const len = guideDir.length();
    const guide = new THREE.Mesh(guideGeo, guideMat);
    guide.name = 'GuideBond';
    guide.position.copy(CENTER).addScaledVector(guideDir, 0.5);
    guide.scale.set(1, len, 1);
    guideDir.normalize();
    guide.quaternion.setFromUnitVectors(up, guideDir);
    root.add(guide);
  }

  const ghostMatO = new THREE.MeshBasicMaterial({ color: 0xe23b2e, transparent: true, opacity: 0.22, depthWrite: false });
  const ghostMatH = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.22, depthWrite: false });
  const ghostO = new THREE.Mesh(new THREE.SphereGeometry(0.038, 32, 16), ghostMatO);
  ghostO.name = 'GhostOxygen';
  ghostO.position.copy(CENTER);
  root.add(ghostO);
  const ghostH1 = new THREE.Mesh(new THREE.SphereGeometry(0.024, 24, 12), ghostMatH);
  ghostH1.name = 'GhostHydrogen1';
  ghostH1.position.copy(TARGET_H1);
  root.add(ghostH1);
  const ghostH2 = new THREE.Mesh(new THREE.SphereGeometry(0.024, 24, 12), ghostMatH);
  ghostH2.name = 'GhostHydrogen2';
  ghostH2.position.copy(TARGET_H2);
  root.add(ghostH2);

  // Real atoms
  const oxygenMat = new THREE.MeshStandardMaterial({ color: 0xd9362b, roughness: 0.35, emissive: 0x7a0e06, emissiveIntensity: 0.4 });
  const hydrogenMat = new THREE.MeshStandardMaterial({ color: 0xf2f4f6, roughness: 0.3, emissive: 0x333333, emissiveIntensity: 0.3 });

  const oxygen = new THREE.Mesh(new THREE.SphereGeometry(0.038, 32, 16), oxygenMat);
  oxygen.name = 'Oxygen';
  oxygen.position.copy(INIT_O);
  root.add(oxygen);

  const h1 = new THREE.Mesh(new THREE.SphereGeometry(0.024, 24, 12), hydrogenMat);
  h1.name = 'Hydrogen1';
  h1.position.copy(INIT_H1);
  root.add(h1);

  const h2 = new THREE.Mesh(new THREE.SphereGeometry(0.024, 24, 12), hydrogenMat);
  h2.name = 'Hydrogen2';
  h2.position.copy(INIT_H2);
  root.add(h2);

  const hydrogens = [h1, h2];

  // Dynamic bonds
  const bondGeo = new THREE.CylinderGeometry(0.007, 0.007, 1, 12);
  const bonds = [];
  for (let i = 0; i < 2; i++) {
    const bond = new THREE.Mesh(
      bondGeo,
      new THREE.MeshStandardMaterial({ color: 0xd9e6f2, roughness: 0.4, transparent: true, opacity: 0.9 })
    );
    bond.name = i === 0 ? 'Bond1' : 'Bond2';
    root.add(bond);
    bonds.push(bond);
  }

  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .o { color: #ff9a8a; font-size: 22px; font-weight: 700; }
      .h { color: #ffffff; font-size: 22px; font-weight: 700; }
      .status { color: #ffe9a8; font-size: 22px; background-color: #2a2415; border-radius: 12px; padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px; }
      .live { color: #a8d8d0; font-size: 20px; }
      .small { color: #9aa3af; font-size: 19px; }
      .row { display: flex; flex-direction: row; gap: 12px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2456c6; }
      .alt { background-color: #3a3f47; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build water: H2O</span>
      <span class="body">Grab the atoms and build a molecule. You have 1 <span class="o">oxygen (O)</span> and 2 <span class="h">hydrogens (H)</span>.</span>
      <span class="body">Make a bent V shape: both hydrogens close to the oxygen, with an angle of about 104 degrees between the bonds. The faint dots show the target shape.</span>
      <span class="status" id="status">Press Check molecule when you think it is water.</span>
      <span class="live" id="live">Live: angle - degrees.</span>
      <div class="row">
        <button class="btn" id="check"><span class="btn-text">Check molecule</span></button>
        <button class="btn alt" id="reset"><span class="btn-text">Reset atoms</span></button>
      </div>
      <span class="small">Tip: bonds appear when a hydrogen is close to oxygen. Release an atom near a faint dot to snap it in place.</span>
    </div>`, { width: 0.32, position: [0.24, 0.24, 0.04], rotationY: -0.30 });
  root.add(info.object3D);

  let built = false;
  let lastLiveTime = -1;
  let lastLiveText = '';

  const _dir = new THREE.Vector3();
  const _v1 = new THREE.Vector3();
  const _v2 = new THREE.Vector3();

  function measure() {
    _v1.subVectors(h1.position, oxygen.position);
    _v2.subVectors(h2.position, oxygen.position);
    const d1 = _v1.length();
    const d2 = _v2.length();
    let angle = 0;
    if (d1 > 0.001 && d2 > 0.001) {
      const cos = Math.max(-1, Math.min(1, _v1.dot(_v2) / (d1 * d2)));
      angle = Math.acos(cos) * 180 / Math.PI;
    }
    return { d1, d2, angle };
  }

  function doCheck() {
    const m = measure();
    const bondOk = m.d1 >= 0.07 && m.d1 <= 0.135 && m.d2 >= 0.07 && m.d2 <= 0.135;
    const angleOk = m.angle >= 85 && m.angle <= 125;
    if (bondOk && angleOk) {
      built = true;
      info.set('status', { text: 'Yes! That is water (H2O). Two O-H bonds and a bent angle of ' + Math.round(m.angle) + ' degrees (real value 104.5 degrees). Well done!' });
    } else {
      built = false;
      let message = '';
      if (m.d1 > 0.135 || m.d2 > 0.135) {
        message = 'Not water yet. At least one hydrogen is too far from oxygen. Bring both H atoms close to O, about 10 cm in this model. Angle now ' + Math.round(m.angle) + ' degrees.';
      } else if (m.d1 < 0.07 || m.d2 < 0.07) {
        message = 'Not water yet. The atoms are overlapping. Move a hydrogen a little away from oxygen so the bond is about 10 cm in this model.';
      } else if (m.angle < 85) {
        message = 'Shape is too narrow. Water is bent open: the angle should be about 104 degrees, not ' + Math.round(m.angle) + '. Spread the hydrogens apart.';
      } else if (m.angle > 125) {
        message = 'Shape is too straight. Water is bent, not a straight line. The angle should be about 104 degrees, not ' + Math.round(m.angle) + '. Bring the hydrogens closer together.';
      } else {
        message = 'Almost water. Adjust the bond lengths a little. Angle now ' + Math.round(m.angle) + ' degrees.';
      }
      info.set('status', { text: message });
    }
  }

  function doReset() {
    built = false;
    oxygen.position.copy(INIT_O);
    h1.position.copy(INIT_H1);
    h2.position.copy(INIT_H2);
    oxygen.scale.set(1, 1, 1);
    h1.scale.set(1, 1, 1);
    h2.scale.set(1, 1, 1);
    info.set('status', { text: 'Atoms reset. Build the bent H-O-H shape again and press Check molecule.' });
  }

  info.on('check', 'click', doCheck);
  info.on('reset', 'click', doReset);

  traits(oxygen, { grab: true });
  traits(h1, { grab: true });
  traits(h2, { grab: true });

  return {
    root,
    update(time) {
      // Gentle snapping to the target dots when released close to them
      if (!isGrabbed(oxygen) && oxygen.position.distanceTo(CENTER) < 0.04) {
        oxygen.position.lerp(CENTER, 0.18);
      }
      const d00 = h1.position.distanceTo(TARGETS[0]);
      const d01 = h1.position.distanceTo(TARGETS[1]);
      const d10 = h2.position.distanceTo(TARGETS[0]);
      const d11 = h2.position.distanceTo(TARGETS[1]);
      if (d00 + d11 <= d01 + d10) {
        if (!isGrabbed(h1) && d00 < 0.04) h1.position.lerp(TARGETS[0], 0.18);
        if (!isGrabbed(h2) && d11 < 0.04) h2.position.lerp(TARGETS[1], 0.18);
      } else {
        if (!isGrabbed(h1) && d01 < 0.04) h1.position.lerp(TARGETS[1], 0.18);
        if (!isGrabbed(h2) && d10 < 0.04) h2.position.lerp(TARGETS[0], 0.18);
      }

      if (built && (isGrabbed(oxygen) || isGrabbed(h1) || isGrabbed(h2))) {
        built = false;
      }

      // Bonds follow the atoms
      for (let i = 0; i < hydrogens.length; i++) {
        const bond = bonds[i];
        _dir.subVectors(hydrogens[i].position, oxygen.position);
        const len = _dir.length();
        if (len > 0.001 && len < 0.22) {
          bond.visible = true;
          bond.position.copy(oxygen.position).addScaledVector(_dir, 0.5);
          bond.scale.set(1, len, 1);
          _dir.normalize();
          bond.quaternion.setFromUnitVectors(up, _dir);
          bond.material.opacity = len <= 0.145 ? 0.95 : 0.35;
          bond.material.color.setHex(built ? 0x53d769 : 0xd9e6f2);
        } else {
          bond.visible = false;
        }
      }

      // Success pulse
      const pulse = built ? 1 + 0.07 * Math.sin(time * 6) : 1;
      oxygen.scale.setScalar(pulse);
      h1.scale.setScalar(pulse);
      h2.scale.setScalar(pulse);
      oxygenMat.emissiveIntensity = built ? 0.7 + 0.35 * Math.sin(time * 6) : 0.4;
      hydrogenMat.emissiveIntensity = built ? 0.55 + 0.25 * Math.sin(time * 6) : 0.3;

      // Live readout, throttled
      if (time - lastLiveTime > 0.25) {
        lastLiveTime = time;
        const m = measure();
        const text = 'Live: angle ' + Math.round(m.angle) + ' degrees. O-H distances ' + Math.round(m.d1 * 100) + ' cm and ' + Math.round(m.d2 * 100) + ' cm (model).';
        if (text !== lastLiveText) {
          lastLiveText = text;
          info.set('live', { text });
        }
      }
    }
  };
}

