  banana.add(tipA);

  const tipB = new THREE.Mesh(new THREE.SphereGeometry(0.008, 12, 8), tipMaterial);
  tipB.position.set(0.038, 0.012, 0);
  banana.add(tipB);

  traits(apple, { grab: true });
  traits(orange, { grab: true });
  traits(banana, { grab: true });

  const entries = [
    {
      obj: apple,
      name: 'Apple',
      price: 1.2,
      home: new THREE.Vector3(-0.29, 0.032, 0.08),
      slot: new THREE.Vector3(0.115, 0.042, 0.025),
      inBasket: false,
      settling: false
    },
    {
      obj: orange,
      name: 'Orange',
      price: 1.6,
      home: new THREE.Vector3(-0.29, 0.031, -0.03),
      slot: new THREE.Vector3(0.205, 0.041, 0.02),
      inBasket: false,
      settling: false
    },
    {
      obj: banana,
      name: 'Banana',
      price: 0.9,
      home: new THREE.Vector3(-0.29, 0.032, -0.13),
      slot: new THREE.Vector3(0.16, 0.04, -0.03),
      inBasket: false,
      settling: false
    }
  ];

  const info = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 9px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 31px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .prices { color: #ffd166; font-size: 22px; font-weight: 700; }
      .basket-text { color: #a8d5ba; font-size: 23px; font-weight: 700; }
      .total { color: #ffd166; font-size: 29px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2e7d46; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket Shop</span>
      <span class="body">Pinch a fruit, carry it, and drop it inside the basket.</span>
      <span class="prices">Apple $1.20 - Orange $1.60 - Banana $0.90</span>
      <span class="basket-text" id="basket">Basket: empty</span>
      <span class="total" id="total">Total: $0.00</span>
      <span class="body" id="count">0 of 3 fruits in the basket</span>
      <span class="body" id="msg">Start by pinching a fruit.</span>
      <button class="btn" id="reset"><span class="btn-text">Reset fruits</span></button>
    </div>`, { width: 0.35, position: [0, 0.35, -0.04], rotationY: 0 });
  root.add(info.object3D);

  function refresh() {
    const inside = [];
    let total = 0;
    for (const entry of entries) {
      if (entry.inBasket) {
        inside.push(entry.name);
        total += entry.price;
      }
    }
    info.set('basket', { text: inside.length > 0 ? 'Basket: ' + inside.join(', ') : 'Basket: empty' });
    info.set('total', { text: 'Total: $' + total.toFixed(2) });
    info.set('count', { text: inside.length + ' of 3 fruits in the basket' });
  }

  refresh();

  info.on('reset', 'click', () => {
    for (const entry of entries) {
      entry.inBasket = false;
      entry.settling = false;
      entry.obj.position.copy(entry.home);
      entry.obj.quaternion.copy(identityQuat);
    }
    refresh();
    info.set('msg', { text: 'Fruits reset. Total is $0.00.' });
  });

  return {
    root,
    update(time, delta) {
      const step = Math.min(1, delta * 8);
      for (const entry of entries) {
        if (isGrabbed(entry.obj)) {
          if (entry.inBasket) {
            entry.inBasket = false;
            entry.settling = false;
            refresh();
            info.set('msg', { text: entry.name + ' taken out of the basket.' });
          }
          continue;
        }

        if (entry.settling) {
          entry.obj.position.lerp(entry.slot, step);
          entry.obj.quaternion.slerp(identityQuat, step);
          if (entry.obj.position.distanceToSquared(entry.slot) < 0.000004) {
            entry.obj.position.copy(entry.slot);
            entry.settling = false;
          }
          continue;
        }

        if (!entry.inBasket) {
          const dx = entry.obj.position.x - basketCenter.x;
          const dz = entry.obj.position.z - basketCenter.z;
          if (
            Math.abs(dx) < 0.07 &&
            Math.abs(dz) < 0.055 &&
            entry.obj.position.y > 0.015 &&
            entry.obj.position.y < 0.25
          ) {
            entry.inBasket = true;
            entry.settling = true;
            refresh();
            info.set('msg', { text: entry.name + ' added to the basket.' });
          }
        }
      }
    }
  };
}

