  );
  ghostH2.name = 'GhostHydrogen2';
  ghostH2.position.set(0.049, 0.082, 0.06);
  ghostGroup.add(ghostH2);

  const arcPoints = [];
  for (let i = 0; i <= 24; i++) {
    const a = (-142.25 + (i * 104.5) / 24) * Math.PI / 180;
    arcPoints.push(new THREE.Vector3(Math.cos(a) * 0.032, 0.12 + Math.sin(a) * 0.032, 0.06));
  }
  const arc = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(arcPoints),
    new THREE.LineBasicMaterial({ color: 0xffd166, transparent: true, opacity: 0.7 })
  );
  arc.name = 'GhostAngleArc';
  ghostGroup.add(arc);

  const ghostBonds = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0, 0.12, 0.06),
      new THREE.Vector3(-0.049, 0.082, 0.06),
      new THREE.Vector3(0, 0.12, 0.06),
      new THREE.Vector3(0.049, 0.082, 0.06),
    ]),
    new THREE.LineBasicMaterial({ color: 0xffd166, transparent: true, opacity: 0.5 })
  );
  ghostGroup.add(ghostBonds);

  const ring = new THREE.Mesh(
    new THREE.RingGeometry(0.036, 0.04, 36),
    new THREE.MeshBasicMaterial({ color: 0xffd166, transparent: true, opacity: 0.45, side: THREE.DoubleSide })
  );
  ring.name = 'GhostTargetRing';
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(0, 0.013, 0.06);
  ghostGroup.add(ring);

  // Grabbable atoms: 2 oxygen and 4 hydrogen, so extra atoms can make wrong builds
  const atoms = [];
  const oxygens = [];
  const hydrogens = [];

  const atomDefs = [
    { el: 'O', name: 'Oxygen', home: [-0.2, 0.046, 0.13] },
    { el: 'O', name: 'Oxygen', home: [-0.2, 0.046, -0.02] },
    { el: 'H', name: 'Hydrogen', home: [0.02, 0.033, 0.15] },
    { el: 'H', name: 'Hydrogen', home: [0.13, 0.033, 0.09] },
    { el: 'H', name: 'Hydrogen', home: [0.02, 0.033, -0.03] },
    { el: 'H', name: 'Hydrogen', home: [0.13, 0.033, -0.09] },
  ];

  for (let i = 0; i < atomDefs.length; i++) {
    const def = atomDefs[i];
    const isOxygen = def.el === 'O';
    const mat = new THREE.MeshStandardMaterial({
      color: isOxygen ? 0xd9381e : 0xf2f2f2,
      roughness: isOxygen ? 0.35 : 0.5,
      emissive: isOxygen ? 0x7a130b : 0x666666,
      emissiveIntensity: isOxygen ? 0.35 : 0.15,
    });
    const mesh = new THREE.Mesh(isOxygen ? oxygenGeo : hydrogenGeo, mat);
    mesh.name = def.name;
    mesh.position.set(def.home[0], def.home[1], def.home[2]);
    root.add(mesh);
    const atom = {
      mesh: mesh,
      el: def.el,
      mat: mat,
      home: new THREE.Vector3(def.home[0], def.home[1], def.home[2]),
      bonded: false,
    };
    atoms.push(atom);
    if (isOxygen) oxygens.push(atom); else hydrogens.push(atom);
  }

  // Bond cylinders that appear between close O-H pairs
  const bondGeo = new THREE.CylinderGeometry(0.0055, 0.0055, 1, 10);
  const bondMat = new THREE.MeshStandardMaterial({ color: 0xd7dde6, roughness: 0.4 });
  const bonds = [];
  for (let i = 0; i < 8; i++) {
    const b = new THREE.Mesh(bondGeo, bondMat);
    b.name = 'Bond';
    b.visible = false;
    root.add(b);
    bonds.push(b);
  }

  // Info and check panel
  const info = ui(`
    <style>
      .card { display: flex; width: 500px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; border-width: 2px; border-color: #3a3f47; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 20px; text-align: center; }
      .picked { color: #a8c8ff; font-size: 20px; text-align: center; }
      .status { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
      .result { color: #d7dbe2; font-size: 20px; font-weight: 700; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 8px; justify-content: center; align-items: center; }
      .btnCheck { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2e9e5b; }
      .btnReset { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; }
      .btnGhost { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #4a4f58; }
      .btnText { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build Water (H2O)</span>
      <span class="body">Pinch a ball and move it. Bond 2 white H atoms to 1 red O atom.</span>
      <span class="picked" id="picked">Red large = Oxygen (O). White small = Hydrogen (H).</span>
      <span class="status" id="status">No bonds yet. Move a white H to a red O.</span>
      <span class="result" id="result">Press Check when you think you are done.</span>
      <div class="row">
        <button class="btnCheck" id="check"><span class="btnText">Check my molecule</span></button>
        <button class="btnReset" id="reset"><span class="btnText">Reset atoms</span></button>
        <button class="btnGhost" id="ghost"><span class="btnText">Ghost</span></button>
      </div>
    </div>`, { width: 0.4, position: [0, 0.345, -0.14], rotationY: 0 });
  root.add(info.object3D);

  // Molecule state, computed without allocating in update
  let stateType = 'none';
  let stateAngle = 0;
  let stateCount = 0;
  const v1 = new THREE.Vector3();
  const v2 = new THREE.Vector3();

  function computeState() {
    stateType = 'none';
    stateAngle = 0;
    stateCount = 0;
    let bestCount = 0;
    let bestAngle = 0;
    let bestTooMany = false;
    let foundGood = false;

    for (let oi = 0; oi < oxygens.length && !foundGood; oi++) {
      const o = oxygens[oi].mesh.position;
      let count = 0;
      let d1 = Infinity;
      let d2 = Infinity;
      let h1 = null;
      let h2 = null;

      for (let hi = 0; hi < hydrogens.length; hi++) {
        const h = hydrogens[hi].mesh.position;
        const dx = h.x - o.x;
        const dy = h.y - o.y;
        const dz = h.z - o.z;
        const distSq = dx * dx + dy * dy + dz * dz;
        if (distSq < BOND_DIST_SQ) {
          count++;
          if (distSq < d1) {
            d2 = d1; h2 = h1; d1 = distSq; h1 = h;
          } else if (distSq < d2) {
            d2 = distSq; h2 = h;
          }
        }
      }

      let angle = 0;
      if (count >= 2 && h1 && h2) {
        v1.subVectors(h1, o).normalize();
        v2.subVectors(h2, o).normalize();
        let dot = v1.dot(v2);
        if (dot > 1) dot = 1;
        if (dot < -1) dot = -1;
        angle = Math.acos(dot) * 180 / Math.PI;
        if (count === 2 && angle >= 75 && angle <= 135) {
          foundGood = true;
          stateType = 'good';
          stateAngle = angle;
          stateCount = count;
        }
      }

      if (!foundGood && count > bestCount) {
        bestCount = count;
        bestAngle = angle;
        bestTooMany = count > 2;
      }
    }

    if (foundGood) return;
    if (bestCount >= 2) {
      stateType = bestTooMany ? 'many' : 'angle';
      stateAngle = bestAngle;
      stateCount = bestCount;
    } else if (bestCount === 1) {
      stateType = 'one';
      stateCount = 1;
    } else {
      stateType = 'none';
      stateCount = 0;
    }
  }

  info.on('check', 'click', () => {
    computeState();
    if (stateType === 'good') {
      info.set('result', { text: 'Correct! That is water (H2O), angle ' + Math.round(stateAngle) + ' degrees.', color: '#9ef0b0' });
    } else if (stateType === 'many') {
      info.set('result', { text: 'Not yet. Too many hydrogens on one oxygen. Water needs exactly 2.', color: '#ffb4a2' });
    } else if (stateType === 'angle') {
      info.set('result', { text: 'Not yet. The H-O-H angle is ' + Math.round(stateAngle) + ' degrees. Water is bent at about 104 degrees.', color: '#ffb4a2' });
    } else if (stateType === 'one') {
      info.set('result', { text: 'Not yet. Only 1 hydrogen is bonded to oxygen. Add another H to the same O.', color: '#ffb4a2' });
    } else {
      info.set('result', { text: 'Not yet. No hydrogen is touching oxygen. Move 2 white H atoms to 1 red O.', color: '#ffb4a2' });
    }
  });

  info.on('reset', 'click', () => {
    for (let i = 0; i < atoms.length; i++) {
      atoms[i].mesh.position.copy(atoms[i].home);
    }
    info.set('picked', { text: 'Red large = Oxygen (O). White small = Hydrogen (H).', color: '#a8c8ff' });
    info.set('result', { text: 'Press Check when you think you are done.', color: '#d7dbe2' });
  });

  let ghostOn = true;
  info.on('ghost', 'click', () => {
    ghostOn = !ghostOn;
    ghostGroup.visible = ghostOn;
    info.set('result', { text: ghostOn ? 'Ghost template on. Match the faint balls.' : 'Ghost template off. Use your own bent shape.', color: '#d7dbe2' });
  });

  // Grabbing and identification
  for (let i = 0; i < atoms.length; i++) {
    const atom = atoms[i];
    traits(atom.mesh, {
      grab: true,
      onPress: () => {
        if (atom.el === 'O') {
          info.set('picked', { text: 'Oxygen (O): the large red atom. It bonds to 2 H atoms.', color: '#ffffff' });
        } else {
          info.set('picked', { text: 'Hydrogen (H): a small white atom. Two of them bond to 1 O.', color: '#ffffff' });
        }
      },
    });
  }

  const UP = new THREE.Vector3(0, 1, 0);
  const tmpDir = new THREE.Vector3();
  let lastStatusKey = '';

  return {
    root,
    update(time, delta) {
      // Update bonds and bonded highlights. Atom positions are never animated here,
      // so a grabbed atom is never fought by the update.
      for (let i = 0; i < atoms.length; i++) atoms[i].bonded = false;

      let bondIndex = 0;
      for (let oi = 0; oi < oxygens.length; oi++) {
        const oAtom = oxygens[oi];
        const o = oAtom.mesh.position;
        for (let hi = 0; hi < hydrogens.length; hi++) {
          const hAtom = hydrogens[hi];
          const h = hAtom.mesh.position;
          const dx = h.x - o.x;
          const dy = h.y - o.y;
          const dz = h.z - o.z;
          const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
          if (dist < BOND_DIST && bondIndex < bonds.length) {
            const bond = bonds[bondIndex];
            bondIndex++;
            bond.visible = true;
            bond.position.set((o.x + h.x) / 2, (o.y + h.y) / 2, (o.z + h.z) / 2);
            tmpDir.set(dx, dy, dz).normalize();
            bond.quaternion.setFromUnitVectors(UP, tmpDir);
            bond.scale.set(1, dist, 1);
            oAtom.bonded = true;
            hAtom.bonded = true;
          }
        }
      }
      for (let i = bondIndex; i < bonds.length; i++) bonds[i].visible = false;

      for (let i = 0; i < atoms.length; i++) {
        const atom = atoms[i];
        atom.mat.emissiveIntensity = atom.bonded ? (atom.el === 'O' ? 1.0 : 0.6) : (atom.el === 'O' ? 0.35 : 0.15);
      }

      computeState();
      const key = stateType + ':' + (stateType === 'angle' ? Math.round(stateAngle) : 0);
      if (key !== lastStatusKey) {
        lastStatusKey = key;
        if (stateType === 'none') {
          info.set('status', { text: 'No bonds yet. Move a white H to a red O.', color: '#ffffff' });
        } else if (stateType === 'one') {
          info.set('status', { text: '1 bond formed. Add a second H to the same O.', color: '#ffd166' });
        } else if (stateType === 'good') {
          info.set('status', { text: 'Bent shape looks right. Press Check.', color: '#9ef0b0' });
        } else if (stateType === 'angle') {
          info.set('status', { text: 'Angle is ' + Math.round(stateAngle) + ' degrees. Make a bent shape near 104 degrees.', color: '#ffb4a2' });
        } else {
          info.set('status', { text: 'Too many H atoms on one O. Water has exactly 2.', color: '#ffb4a2' });
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
