      f.group.rotation.set(0, f.homeRotY, 0);
    }
    updatePanel('Basket emptied. Pinch a fruit to start again.');
  });

  for (const f of fruits) {
    traits(f.group, { grab: true });
  }
  traits(basket, {
    onPress: () => info.set('message', { text: 'Basket total is ' + money(basketTotal()) + ' for ' + basketCount() + ' item(s).' })
  });

  updatePanel();

  return {
    root,
    update(time, delta) {
      const dt = delta && delta > 0 ? delta : 0.016;
      const settle = Math.min(1, dt * 7);
      const move = Math.min(1, dt * 9);
      let hovering = false;

      for (const f of fruits) {
        const dx = f.group.position.x - basketPos.x;
        const dz = f.group.position.z - basketPos.z;
        const distSq = dx * dx + dz * dz;

        if (isGrabbed(f.group)) {
          if (f.inBasket) {
            f.inBasket = false;
            updatePanel();
          }
          if (distSq < 0.085 * 0.085) hovering = true;
          continue;
        }

        if (f.inBasket) {
          f.group.position.lerp(f.slot, move);
          f.group.rotation.y += (f.slotRotY - f.group.rotation.y) * move;
          continue;
        }

        if (distSq < 0.085 * 0.085 && f.group.position.y < 0.17) {
          f.inBasket = true;
          updatePanel();
          continue;
        }

        f.group.position.y += (f.restY - f.group.position.y) * settle;
        f.group.position.x = THREE.MathUtils.clamp(f.group.position.x, -0.36, 0.36);
        f.group.position.z = THREE.MathUtils.clamp(f.group.position.z, -0.14, 0.20);
      }

      rimMat.emissiveIntensity = hovering ? 0.9 : 0.18;
    }
  };
}
